(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c14"]=[{"id":"00013023","register_sub_id":"101","register_pk":"368333","name":"福西本店座敷蔵","kana":"ふくにしほんてんざしきぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"福島県","address":"福島県会津若松市中町321他","lat":37.49752222,"lng":139.92746944,"geo_status":"db","era":"明治19年／平成28年改修","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積74㎡","structure_material":"土蔵造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"07 － 0216","desc":"敷地北辺中央に東西棟で建つ。外壁は漆喰塗で、腰を板張とする。主屋の主人室東から延びる廊下に戸口を開き、黒漆喰塗の扉を両開きとする。１階は改修で１室としたが元は３室で、床、棚、書院は中室に設けていた。木部は透漆塗で華やかな造作の座敷蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013023"},{"id":"00013021","register_sub_id":"101","register_pk":"368331","name":"福西本店袖蔵","kana":"ふくにしほんてんそでぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"福島県","address":"福島県会津若松市中町321他","lat":37.49758333,"lng":139.92724167,"geo_status":"db","era":"明治19年／平成28年改修","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積46㎡","structure_material":"土蔵造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"07 － 0214","desc":"街路に面し店蔵の北に建つ東西棟である。外壁は黒漆喰塗で、西妻の窓上に銅板葺の小庇をつける。南の店蔵１階と東の蔵前に戸口を開き、西半は商品倉庫、東半の６畳は床棚を備えた仏間とする。２階は家財を収めた。店蔵と統一した外観が街路景観を引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013021"},{"id":"00013025","register_sub_id":"101","register_pk":"368335","name":"福西本店離座敷","kana":"ふくにしほんてんはなれざしき","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"福島県","address":"福島県会津若松市中町321他","lat":37.49735556,"lng":139.92752778,"geo_status":"db","era":"昭和5年頃／平成28年改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、瓦葺一部金属板葺、建築面積78㎡","structure_material":"木造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"07 － 0218","desc":"若夫婦用に建てたと伝わり、主屋の東に接続する。１階は６畳２室、２階は８畳と６畳の続き間座敷で、北から東へ廻らせた縁にガラス障子を建込み、東の庭を望む。１階は木部を透漆塗、２階は素木として雰囲気を異にする。丁寧な造作の数寄屋風住宅である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013025"},{"id":"00013020","register_sub_id":"101","register_pk":"368330","name":"福西本店店蔵","kana":"ふくにしほんてんみせぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"福島県","address":"福島県会津若松市中町321他","lat":37.49750278,"lng":139.92719167,"geo_status":"db","era":"大正3年頃／昭和60年代・平成28年改修","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積102㎡","structure_material":"土蔵造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"07 － 0213","desc":"街路に西面し、正面下屋に看板台を揚げる。外壁は黒漆喰塗で２階窓は銅板張の両開きとする。１階は下屋境にイオニア式円柱を立て、上がり框は隅を円弧に作り、天井など木部は透漆塗とする。２階は８畳座敷と洋間である。重厚な外観と美麗な内装の店蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013020"},{"id":"00013026","register_sub_id":"101","register_pk":"368336","name":"福西本店煉瓦塀","kana":"ふくにしほんてんれんがべい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"福島県","address":"福島県会津若松市中町321他","lat":37.49758333,"lng":139.92732778,"geo_status":"db","era":"大正4年頃","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"煉瓦造、延長12m","structure_material":"煉瓦造","registered":"2019.12.05(令和1.12.05)","register_no":"07 － 0219","desc":"敷地の北辺、袖蔵と蔵座敷の間を隣地と仕切り、主屋北の中庭の背景となる。袖蔵の蔵前と主屋の店主室に沿う部分は高く、中庭部分は低く切り下げて造る。基礎は切石で、煉瓦のイギリス積とし、上部に瓦を葺く。延焼に備えつつ、敷地北面の景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013026"},{"id":"00013946","register_sub_id":"101","register_pk":"508206","name":"若喜商店作業蔵","kana":"わかきしょうてんさぎょうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"福島県","address":"福島県喜多方市字三丁目4786","lat":37.649825,"lng":139.87160556,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積130㎡","structure_material":"土蔵造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"07 - 0271","desc":"敷地南西の醸造場南に接する東西棟の土蔵造二階建、切妻造桟瓦葺の建物。漆喰仕上鉢巻付で軒まで塗込み、腰を板張。桁行が長く中間で仕切り、東側は瓶詰作業場で、通りに近い西側は出荷倉庫で妻面に出入口を開く。醸造業を営む商家の屋敷構えの一画をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013946"},{"id":"00013945","register_sub_id":"101","register_pk":"508205","name":"若喜商店醸造場","kana":"わかきしょうてんじょうぞうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県喜多方市字三丁目4786","lat":37.649925,"lng":139.87169167,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積252㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"07 - 0270","desc":"味噌醤油醸造元の主屋南東に建つ南北棟の木造二階建で、切妻造桟瓦葺、梁間五間半にトラスを架けた大空間の醸造場。内部は西寄りに高床式作業指示所や北側に二階を設ける。一連の醸造施設の中核をなし、東側に立つ煉瓦造煙突が特色ある景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013945"},{"id":"00015137","register_sub_id":"101","register_pk":"530561","name":"羽前絹練株式会社検査棟","kana":"うぜんけんれんかぶしきがいしゃけんさとう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"山形県","address":"山形県鶴岡市新海町21-3","lat":38.72838333,"lng":139.81709444,"geo_status":"db","era":"昭和18年頃","year":1943,"year_source":"db","year_min":1943,"year_max":1943,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積357㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"06 - 0227","desc":"敷地の南端に位置し、生地を目視検査した後、出荷用に分割する検査棟。平屋建切妻造桟瓦葺、外壁は下見板張。内部は一室の板間で、かつては北側に窓を開け、自然光を用いて検査した。簡素なつくりながら昭和戦前の精練の様相を伝え、敷地南辺の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015137"},{"id":"00015132","register_sub_id":"101","register_pk":"530556","name":"羽前絹練株式会社事務所及び仕立棟","kana":"うぜんけんれんかぶしきがいしゃじむしょおよびしたてとう","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和前","pref":"山形県","address":"山形県鶴岡市新海町21-5他","lat":38.72854722,"lng":139.81762778,"geo_status":"db","era":"昭和15年／昭和中期増築","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積705㎡","structure_material":"木造平屋一部2階建","registered":"2024.12.03(令和6.12.03)","register_no":"06 - 0222","desc":"鶴ヶ岡城跡西方にある絹織物精練工場の事務所及び仕立棟。敷地北東に建つ二階建の事務所は北に玄関を付し、南に平屋建の仕立棟を接続。仕立棟には反物を木枠に巻取り、精練用に仕立てる一四〇畳の準備室を配す。切妻屋根を重ねた外観が工場の表構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015132"},{"id":"00015133","register_sub_id":"101","register_pk":"530557","name":"羽前絹練株式会社精練棟","kana":"うぜんけんれんかぶしきがいしゃせいれんとう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"山形県","address":"山形県鶴岡市新海町21-5他","lat":38.72886667,"lng":139.81744167,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺及び鉄板葺、建築面積368㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"06 - 0223","desc":"仕立棟の北側に位置し、絹織物を水槽で煮て不純物を除去する作業棟。Ｌ字形平面で切妻屋根頂部の越屋根と南・北面の開口から高熱の蒸気を排出。内部は土間で、生地を水槽に移動するレールをクイーンポスト・トラス下に設える。工場の中核をなす施設の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015133"},{"id":"00015134","register_sub_id":"101","register_pk":"530558","name":"羽前絹練株式会社染色棟（旧染色室及び旧汽罐室）","kana":"うぜんけんれんかぶしきがいしゃせんしょくとう（きゅうせんしょくしつおよびきゅうきかんしつ）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"山形県","address":"山形県鶴岡市新海町21-5他","lat":38.72892778,"lng":139.81719722,"geo_status":"db","era":"昭和4年／昭和8年頃・同中期増築","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、瓦葺及び鉄板葺、建築面積238㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"06 - 0224","desc":"精練棟の西側に位置し、精練後の生地を染める作業棟。桟瓦葺の旧染色室の東に、セメント瓦葺の旧汽罐室を増築し、両棟を鉄板葺で繋ぐ。各棟内部は一室の土間とし、蒸気の排気のため、棟中央にそれぞれ越屋根を設ける。増築による外観が工場の発展を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015134"},{"id":"00015135","register_sub_id":"101","register_pk":"530559","name":"羽前絹練株式会社第一仕上棟","kana":"うぜんけんれんかぶしきがいしゃだいいちしあげとう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"山形県","address":"山形県鶴岡市新海町21-5他","lat":38.728725,"lng":139.81739722,"geo_status":"db","era":"大正後期／昭和前期増築","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺及び鉄板葺、建築面積391㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"06 - 0225","desc":"工場の中心部に位置し、精練・染色後にすすぎ・脱水・乾燥の仕上工程を担う棟。平屋建で西を寄棟造、東を切妻造とする桟瓦葺の東西棟で、外壁下見板張。内部は土間で上部にキングポスト・トラスを現す。棟に設けた採光・換気用の越屋根が工場景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015135"},{"id":"00015136","register_sub_id":"101","register_pk":"530560","name":"羽前絹練株式会社第二仕上棟","kana":"うぜんけんれんかぶしきがいしゃだいにしあげとう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"山形県","address":"山形県鶴岡市新海町21-5他","lat":38.72862778,"lng":139.81717778,"geo_status":"db","era":"大正後期／昭和中期増築","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺及び鉄板葺、建築面積368㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"06 - 0226","desc":"第一仕上棟の南に位置し、乾燥収縮した生地を整える作業棟。東西に長い平屋建切妻造桟瓦葺で外壁横板張。棟中央に換気・採光用の越屋根を設ける。内部は土間に巻取機など並べ、上部にキングポスト・トラスを現す。桁行長大で工場中央部の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015136"},{"id":"00015138","register_sub_id":"101","register_pk":"530562","name":"羽前絹練株式会社土蔵","kana":"うぜんけんれんかぶしきがいしゃどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"山形県","address":"山形県鶴岡市新海町21-5他","lat":38.72844167,"lng":139.81734444,"geo_status":"db","era":"大正後期／昭和15年移築","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造2階建、瓦葺、建築面積75㎡","structure_material":"木造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"06 - 0228","desc":"事務所及び仕立棟の南端に接続する製品保管用の蔵。桁行六間梁間三間、土蔵造二階建、切妻造妻入桟瓦葺、外壁は漆喰塗仕上。東妻に戸口を開け、内部は各階一室の板敷とし、二階上部にキングポスト・トラスを現す。戸口に掛子塗扉を吊り重厚なつくりの土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015138"},{"id":"00016350","register_sub_id":"101","register_pk":"536417","name":"オリエンタルカーペット株式会社事務所棟","kana":"おりえんたるかーぺっとかぶしきがいしゃじむしょとう","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和中","pref":"山形県","address":"山形県東村山郡山辺町大字山辺字楯21-1他","lat":38.29496389,"lng":140.2662,"geo_status":"db","era":"昭和23年／昭和35年改修","year":1948,"year_source":"db","year_min":1948,"year_max":1948,"year_label":null,"structure":"木造3階建、鉄板葺、建築面積177㎡","structure_material":"木造3階建","registered":"2025.11.17(令和7.11.17)","register_no":"06 - 0229","desc":"市街地の中心部に位置する絨毯製造会社の事務所。敷地入口近くに建つ、木造三階建、半切妻造鉄板葺で、1、2階の南側や西側を外に張り出す。外壁は下見板張で、一階の腰に緑色タイルを貼る。旧図案室の三階は水平に窓を連続して開く、開放的な外観の事務所。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016350"},{"id":"00016352","register_sub_id":"101","register_pk":"536419","name":"オリエンタルカーペット株式会社染色棟","kana":"おりえんたるかーぺっとかぶしきがいしゃせんしょくとう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和中","pref":"山形県","address":"山形県東村山郡山辺町大字山辺字楯21-1他","lat":38.29488333,"lng":140.266475,"geo_status":"db","era":"昭和23年／昭和25年・同41年・同47年増築","year":1948,"year_source":"db","year_min":1948,"year_max":1948,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積263㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"06 - 0231","desc":"緞通棟の北方に建つ絨毯の染色工場。平屋建半切妻造鉄板葺の屋根にドーマー窓を設け、棟中央に越屋根を載せる。内部はキングポスト・トラスを用いた無柱の大空間で、染色用機械を配す。外壁は下見板張と漆喰壁で、ガラス窓を多く開け、開放的な外観の染色棟。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016352"},{"id":"00016351","register_sub_id":"101","register_pk":"536418","name":"オリエンタルカーペット株式会社緞通棟","kana":"おりえんたるかーぺっとかぶしきがいしゃだんつうとう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"山形県","address":"山形県東村山郡山辺町大字山辺字楯21-1他","lat":38.29470278,"lng":140.26639722,"geo_status":"db","era":"昭和23年／昭和37年・同47年改修","year":1948,"year_source":"db","year_min":1948,"year_max":1948,"year_label":null,"structure":"木造平屋一部2階建、鉄板葺、建築面積365㎡","structure_material":"木造平屋一部2階建","registered":"2025.11.17(令和7.11.17)","register_no":"06 - 0230","desc":"敷地南側中央に建つ絨毯の織工場。木造平屋建半切妻造鉄板葺を二棟連ね、外壁は下見板張と漆喰塗。柱や窓枠を桃色に塗装する。内部はキングポスト・トラスを用いた無柱の大空間に織機を配す。屋根のドーマー窓が特徴的な外観で地域産業の様相を伝える緞通棟。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016351"},{"id":"00016353","register_sub_id":"101","register_pk":"536420","name":"オリエンタルカーペット株式会社マーセライズ棟","kana":"おりえんたるかーぺっとかぶしきがいしゃまーせらいずとう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"山形県","address":"山形県東村山郡山辺町大字山辺字東町279他","lat":38.2948,"lng":140.26681389,"geo_status":"db","era":"昭和25年／昭和中期増築","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造平屋一部2階建、鉄板葺、建築面積406㎡","structure_material":"木造平屋一部2階建","registered":"2025.11.17(令和7.11.17)","register_no":"06 - 0232","desc":"染色棟東隣に建つ、絨毯染色後の艶出加工及び洗濯を行う工場。木造平屋建、半切妻造鉄板葺で棟に三箇所の越屋根を設け、外壁に窓を並べる。西側の乾燥場と洗濯場は吹抜とし、陸梁中央を高めて繋ぐキングポスト・トラスを現す。敷地内に統一的な景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016353"},{"id":"00013215","register_sub_id":"101","register_pk":"366204","name":"旧遠万織物（創匠庵）主屋","kana":"きゅうえんまんおりもの（そうしょうあん）おもや","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"山形県","address":"山形県米沢市門東町一丁目1028","lat":37.90660833,"lng":140.11109722,"geo_status":"db","era":"大正後期／平成19年改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積200㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"06 － 0194","desc":"米沢城旧城下町に建つ織物業者の主屋。敷地東寄りに南面して建ち、木造平屋建、桟瓦葺で、道路側を入母屋造とする。6室からなる居室部は天井が高く上質な造りで、その西側の旧台所部は落棟としてトラス組の小屋を現しとする。米沢の織物業の繁栄を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013215"},{"id":"00013217","register_sub_id":"101","register_pk":"366206","name":"旧遠万織物（創匠庵）新蔵","kana":"きゅうえんまんおりもの（そうしょうあん）しんくら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"山形県","address":"山形県米沢市門東町一丁目1028","lat":37.90673333,"lng":140.11079167,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造2階建、瓦葺、建築面積44㎡","structure_material":"土蔵造2階建","registered":"2020.04.03(令和2.04.03)","register_no":"06 － 0196","desc":"前蔵の北西に建ち、主屋北面から廊下で蔵前と繋ぐ。東西棟の土蔵造二階建妻入で、屋根は桟瓦葺の置屋根とする。外壁は腰を赤瓦の海鼠壁とし、上部は四隅に柱形を現し、鉢巻を廻す。窓回りには雪囲いを設け、ガラス窓を穿つ。織物業者の屋敷構えを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013217"},{"id":"00013216","register_sub_id":"101","register_pk":"366205","name":"旧遠万織物（創匠庵）前蔵","kana":"きゅうえんまんおりもの（そうしょうあん）まえのくら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"山形県","address":"山形県米沢市門東町一丁目1028","lat":37.9067,"lng":140.1109,"geo_status":"db","era":"明治6年／平成19年改修","year":1873,"year_source":"db","year_min":1873,"year_max":1873,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積55㎡","structure_material":"土蔵造2階建","registered":"2020.04.03(令和2.04.03)","register_no":"06 － 0195","desc":"主屋の西側に接続し、主屋旧台所部に入り口を開く。東西棟の二階建妻入の土蔵で、桁行5間、梁間3間、屋根は桟瓦葺の置屋根とする。外壁は腰を赤瓦の海鼠壁とし、南面の上下階には掛子塗の両開窓を設ける。米沢大火から焼け残った希少な蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013216"},{"id":"00010727","register_sub_id":"101","register_pk":"201562","name":"旧長谷川製糸所繭蔵・糸蔵及び荷造場","kana":"きゅうはせがわせいししょまゆぐら・いとぐらおよびにづくりば","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"山形県","address":"山形県上山市矢来四丁目111-3","lat":38.149619,"lng":140.27846,"geo_status":"db","era":"繭蔵・荷造場 大正15 糸蔵 昭和11","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"繭蔵 土蔵造3階建、鉄板葺 糸蔵 石造平屋建、鉄板葺 荷造場 木造平屋建、鉄板葺 建築面積341㎡","structure_material":"繭蔵 土蔵造3階建","registered":"2015.11.17(平成27.11.17)","register_no":"06 ‐ 0162","desc":"土蔵造三階建の繭蔵の東に石造平屋建の糸蔵を接続し、両蔵の出入口部に木造平屋建の荷造場を附属する。繭蔵は各階一室で内壁を板張、糸蔵は板床、棹縁天井で紙貼壁とし、地階を持つ。製糸工場建築としての希少価値もある建ちの高い土蔵で街路景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010727"},{"id":"00014717","register_sub_id":"101","register_pk":"518975","name":"小嶋総本店一号蔵","kana":"こじまそうほんてんいちごうくら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"山形県","address":"山形県米沢市本町二丁目752他","lat":37.90117778,"lng":140.11093333,"geo_status":"db","era":"明治前期／昭和30年代改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造平屋建、鉄板葺、建築面積146㎡","structure_material":"土蔵造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"06 - 0211","desc":"敷地東辺で主屋南に接続する土蔵造の平屋建切妻造置屋根とする。折置組小屋梁に地棟や棟束なしで合掌を組み、合掌中程を受ける束を桁行貫で固め、小舞下地の屋根裏を現した独特の小屋組。東面に鉄格子入窓を並べ白漆喰塗外壁腰に赤瓦海鼠壁とした長大な土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014717"},{"id":"00014727","register_sub_id":"101","register_pk":"518985","name":"小嶋総本店北板塀","kana":"こじまそうほんてんきたいたべい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"山形県","address":"山形県米沢市本町二丁目752","lat":37.90151944,"lng":140.11101389,"geo_status":"db","era":"大正8年頃","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造、銅板葺、延長16m","structure_material":"木造","registered":"2024.03.06(令和6.03.06)","register_no":"06 - 0221","desc":"敷地の北辺東端で主屋の北庭を囲う板塀である。高さ二・二メートル。東端は南へ折れて主屋に取付く。切石基礎に土台を据え、四段の貫の表裏に縦板を大和打とする。笠木は銅板包で、北東の出隅は交差して突出し、鳥休につくる。敷地北側の景観を引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014727"},{"id":"00014721","register_sub_id":"101","register_pk":"518979","name":"小嶋総本店五号蔵","kana":"こじまそうほんてんごごうくら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"山形県","address":"山形県米沢市本町二丁目752他","lat":37.90078889,"lng":140.11051667,"geo_status":"db","era":"大正11年","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積183㎡","structure_material":"土蔵造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"06 - 0215","desc":"四号蔵の南に建つ南北棟の土蔵造二階建で、切妻造置屋根とする。北妻が戸口で、南妻は道路に向け窓を開く。高い切石基礎に土台を巡らす。外壁は漆喰塗仕上。一階は仕込蔵、二階は物置とする。小屋組はキングポスト・トラス。敷地南側の景観をつくる仕込蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014721"},{"id":"00014724","register_sub_id":"101","register_pk":"518982","name":"小嶋総本店作業場","kana":"こじまそうほんてんさぎょうば","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"low","period":"大正","pref":"山形県","address":"山形県米沢市本町二丁目752他","lat":37.90112778,"lng":140.11066111,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、鉄板葺、建築面積298㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"06 - 0218","desc":"敷地中央に建つ東西棟の木造平屋建で切妻造の鉄板葺とする。一号蔵の西面南端から西へ延びて、南面に三号蔵と四号蔵の戸口が開き蔵前をなす。小屋組はキングポスト・トラス。北にはボイラー室や瓶詰工場が接続する通路兼作業場で敷地中央部の景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014724"},{"id":"00014719","register_sub_id":"101","register_pk":"518977","name":"小嶋総本店三号蔵","kana":"こじまそうほんてんさんごうくら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"山形県","address":"山形県米沢市本町二丁目752他","lat":37.90095,"lng":140.11077222,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、鉄板葺、建築面積151㎡","structure_material":"土蔵造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"06 - 0213","desc":"二号蔵の西に並ぶ土蔵造平屋建。切妻造の置屋根は鉄板葺。北妻に漆喰塗戸両開の戸口を設け、外壁は漆喰塗仕上とする。内部は一室の土間で、小屋梁は一部を二重に架けて、合掌を組み、中程を束で受ける。西側は庇を含めて大屋根を一連で葺降した大規模な土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014719"},{"id":"00014722","register_sub_id":"101","register_pk":"518980","name":"小嶋総本店倉庫","kana":"こじまそうほんてんそうこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"山形県","address":"山形県米沢市本町二丁目752他","lat":37.90071944,"lng":140.11085278,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、鉄板葺、建築面積154㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"06 - 0216","desc":"敷地東辺南端で二号蔵の南に接続する木造平屋建切妻造で鉄板葺とする。二号蔵との取合部は台形平面で東に戸口を設け、外壁は波形鉄板張とする。小屋組はキングポスト・トラスで柱と陸梁を方杖で挟む。内壁は荷摺板を打付ける。敷地南東隅の景観をつくる倉庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014722"},{"id":"00014716","register_sub_id":"101","register_pk":"518974","name":"小嶋総本店店舗兼主屋","kana":"こじまそうほんてんてんぽけんおもや","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"山形県","address":"山形県米沢市本町二丁目752他","lat":37.90140278,"lng":140.11091667,"geo_status":"db","era":"大正8年／昭和前期増築、昭和48年改修","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積343㎡","structure_material":"木造平屋一部2階建","registered":"2024.03.06(令和6.03.06)","register_no":"06 - 0210","desc":"米沢旧城下の造り酒屋で、敷地北端に通りに面して建つ。正面中央に切妻玄関を付したつし二階建。北半が床上で土間寄りの一八畳客間は天井高く、高窓を開く。北に続く座敷は八畳四室を田字に配し、欄間などに意匠を凝らす。間口長大な近代和風の店舗兼主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014716"},{"id":"00014723","register_sub_id":"101","register_pk":"518981","name":"小嶋総本店土蔵","kana":"こじまそうほんてんどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"山形県","address":"山形県米沢市本町二丁目752他","lat":37.90152778,"lng":140.1106,"geo_status":"db","era":"明治前期／昭和49年移築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、鉄板葺、建築面積46㎡","structure_material":"土蔵造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"06 - 0217","desc":"敷地の北辺中央に建つ土蔵造二階建で、切妻造の置屋根を鉄板葺とする。東面に両開の戸口を設け、窓は敷地内側の南面の上下階に開く。外壁は白漆喰塗で、腰を赤瓦の海鼠壁とする。小屋組は敷梁に垂木を掛け渡す。造作丁寧な文庫蔵で、敷地北の景観の要である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014723"},{"id":"00014718","register_sub_id":"101","register_pk":"518976","name":"小嶋総本店二号蔵","kana":"こじまそうほんてんにごうくら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"山形県","address":"山形県米沢市本町二丁目752他","lat":37.90095,"lng":140.11089722,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造平屋建、鉄板葺、建築面積142㎡","structure_material":"土蔵造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"06 - 0212","desc":"敷地の東辺で、一号蔵の南に通路を介して連なる土蔵造の平屋建で、切妻造の置屋根とする。南北両妻戸口に両開漆喰塗戸を吊る。外壁は漆喰塗で腰を赤瓦の海鼠壁とする。小屋組はキングポスト・トラスである。一号蔵と共通の意匠が整った街路景観を創出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014718"},{"id":"00014725","register_sub_id":"101","register_pk":"518983","name":"小嶋総本店三日月稲生社本殿","kana":"こじまそうほんてんみかづきいなりしゃほんでん","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"山形県","address":"山形県米沢市本町二丁目752","lat":37.90143611,"lng":140.11056111,"geo_status":"db","era":"昭和4年／昭和49年移築","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積6.9㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"06 - 0219","desc":"主屋西の中庭に東面して建つ入母屋造、向拝付の祠で銅板葺とする。基壇上に建ち、正面は格子窓とし、両脇間を板壁とする。南面戸口は片引板戸で、内部は折上格天井とする。背面に突出した神棚に切妻屋根を架ける。造り酒屋の屋敷神で木柄太く質実な祠である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014725"},{"id":"00014726","register_sub_id":"101","register_pk":"518984","name":"小嶋総本店門及び板塀","kana":"こじまそうほんてんもんおよびいたべい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"山形県","address":"山形県米沢市本町二丁目752","lat":37.90143889,"lng":140.11103889,"geo_status":"db","era":"大正8年頃","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"門 木造、銅板葺、間口1.9m 板塀 木造、銅板葺、総延長7.8m","structure_material":"門 木造","registered":"2024.03.06(令和6.03.06)","register_no":"06 - 0220","desc":"主屋東の前庭を閉ざす門と板塀。門は一間一戸の腕木門で一軒疎垂木とする。切妻屋根は銅板葺で銅板包の大棟両端を鳥休につくる。門口には引違板戸を建込む。板塀は土台建で四段の貫の表裏に縦板を大和打とする。銅板包笠木の南端も鳥休とした丁寧なつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014726"},{"id":"00014720","register_sub_id":"101","register_pk":"518978","name":"小嶋総本店四号蔵","kana":"こじまそうほんてんよんごうくら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"山形県","address":"山形県米沢市本町二丁目752他","lat":37.90098611,"lng":140.11056944,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造平屋建、鉄板葺、建築面積148㎡","structure_material":"土蔵造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"06 - 0214","desc":"敷地中央、三号蔵西に並ぶ土蔵造平屋建で切妻造置屋根の鉄板葺。切石基礎に煉瓦を二段積み、切石を廻らせ柱を立て、外壁は漆喰塗仕上。内部は１室の土間で小屋組はキングポスト・トラスとし合掌中程に束を立てる。南北両妻に両開き戸口を設けた長大な仕込蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014720"},{"id":"00012094","register_sub_id":"101","register_pk":"352893","name":"佐藤繊維旧紡績工場西棟","kana":"さとうせんいきゅうぼうせきこうじょうにしとう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"山形県","address":"山形県寒河江市元町一丁目19-3他","lat":38.372986,"lng":140.273332,"geo_status":"db","era":"昭和9年頃／昭和27年移築、平成28年改修","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"石造2階建、金属板葺、建築面積434㎡","structure_material":"石造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"06-187","desc":"昭和九年頃に建てられた石造倉庫を、昭和二七年に現在地に移築したもの。桁行四五メートル、梁間九・六メートル、大谷石による総二階建で、キングポストトラスの木造の小屋組を載せ、切妻造鋼板葺とする。四周の壁面上部に石積二段を廻らし鉢巻状とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012094"},{"id":"00012093","register_sub_id":"101","register_pk":"352892","name":"佐藤繊維旧紡績工場東棟","kana":"さとうせんいきゅうぼうせきこうじょうひがしとう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"山形県","address":"山形県寒河江市元町一丁目19-3他","lat":38.37284,"lng":140.273451,"geo_status":"db","era":"昭和9年頃／昭和24年移築、平成28年改修","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"石造平屋建、金属板葺、建築面積359㎡","structure_material":"石造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"06-186","desc":"昭和九年頃に建てられた石造倉庫を、昭和二四年に現在地に移築したもの。桁行三三メートル、梁間一〇・九メートルで、大谷石を積んだ壁体にキングポストトラスの木造の小屋組を載せ、切妻造鋼板葺とする。比較的規模の大きい石造倉庫建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012093"},{"id":"00000322","register_sub_id":"101","register_pk":"101312","name":"樽平酒造主屋","kana":"たるへいしゅぞうしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"山形県","address":"山形県東置賜郡川西町大字中小松2886","lat":38.01386633,"lng":140.04969546,"geo_status":"db","era":"元禄8頃／昭和7改装","year":1695,"year_source":"db","year_min":1695,"year_max":1695,"year_label":null,"structure":"木造2階建，茅葺，建築面積430㎡","structure_material":"木造2階建","registered":"1997.11.05(平成9.11.05)","register_no":"06 － 0010","desc":"元禄年間創業の酒造会社の事務所兼家屋。茅葺きの民家に，２階建て長方形平面の事務所部分を接続する。街路に面した事務所部分と農家型平面の茅葺き民家のコントラストが特徴的で，街道に面した川西町への入口のランドマークとして親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000322"},{"id":"00000328","register_sub_id":"101","register_pk":"101318","name":"樽平酒造樽蔵","kana":"たるへいしゅぞうたるぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"山形県","address":"山形県東置賜郡川西町大字中小松2910-1","lat":38.01389906,"lng":140.05215674,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建，鉄板葺，建築面積142㎡","structure_material":"土蔵造2階建","registered":"1997.11.05(平成9.11.05)","register_no":"06 － 0016","desc":"前蔵の北側，土蔵の東側に建つ。妻面は後補材が付されているが，道路に面した側は当初の構成を残しており，土蔵としては比較的大きめな開口部などが特徴である。現在では間に道路が敷設されているが，樽平酒造の他の建物と連続した景観を作り出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000328"},{"id":"00000326","register_sub_id":"101","register_pk":"101316","name":"樽平酒造土蔵","kana":"たるへいしゅぞうどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"山形県","address":"山形県東置賜郡川西町大字中小松2886","lat":38.01386633,"lng":140.04969546,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建，鉄板葺，建築面積85㎡","structure_material":"土蔵造2階建","registered":"1997.11.05(平成9.11.05)","register_no":"06 － 0014","desc":"長大な中蔵等と異なり，標準的な規模の土蔵である。街路に平行して建ち，平を見せる。軽快な置屋根と壁面のコントラストが特徴。東蔵の妻面から連なる壁面が，街道沿いのランドマークとして広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000326"},{"id":"00000323","register_sub_id":"101","register_pk":"101313","name":"樽平酒造中蔵","kana":"たるへいしゅぞうなかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"山形県","address":"山形県東置賜郡川西町大字中小松2961","lat":38.01326753,"lng":140.04899197,"geo_status":"db","era":"18世紀中頃","year":1750,"year_source":"estimated","year_min":1731,"year_max":1770,"year_label":"18世紀中頃","structure":"土蔵造平屋建，鉄板葺，建築面積428㎡","structure_material":"土蔵造平屋建","registered":"1997.11.05(平成9.11.05)","register_no":"06 － 0011","desc":"主屋に近接して建ち，各蔵の中心部に配置されて樽平酒造の醸造施設の中核部分をなしている。蔵としては桁行の長い点が特徴的で，西側からは長大なファサードが望まれる。酒造施設としての土蔵造建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000323"},{"id":"00000325","register_sub_id":"101","register_pk":"101315","name":"樽平酒造西蔵","kana":"たるへいしゅぞうにしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"山形県","address":"山形県東置賜郡川西町大字中小松2960","lat":38.01326753,"lng":140.04899197,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造平屋建，鉄板葺，建築面積205㎡","structure_material":"土蔵造平屋建","registered":"1997.11.05(平成9.11.05)","register_no":"06 － 0013","desc":"中蔵の北端に，東蔵と相対して建つ。内部には東蔵と同じく醸造タンクを収容している。中蔵と比較するとやや建ちが低いのが相違点で，壁面には開口部を設けていない。中蔵・東蔵と並んで，土蔵造醸造施設の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000325"},{"id":"00000324","register_sub_id":"101","register_pk":"101314","name":"樽平酒造東蔵","kana":"たるへいしゅぞうひがしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"山形県","address":"山形県東置賜郡川西町大字中小松2962","lat":38.01219434,"lng":140.04913193,"geo_status":"db","era":"19世紀初期","year":1805,"year_source":"estimated","year_min":1801,"year_max":1810,"year_label":"19世紀初期","structure":"土蔵造平屋建，鉄板葺，建築面積162㎡","structure_material":"土蔵造平屋建","registered":"1997.11.05(平成9.11.05)","register_no":"06 － 0012","desc":"中蔵の北端に直角に接続して建つ。現在は主に醸造タンクを収容しており，醸造施設の一端を担っている。東側の妻は街路に接し，隣接する建物と共に三角の屋根端を見せ，リズミカルな景観を形成しており，主屋と共に川西町のランドマークとして親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000324"},{"id":"00000327","register_sub_id":"101","register_pk":"101317","name":"樽平酒造前蔵","kana":"たるへいしゅぞうまえぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"山形県","address":"山形県東置賜郡川西町大字中小松2910-1","lat":38.01389906,"lng":140.05215674,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建，鉄板葺，建築面積79㎡","structure_material":"土蔵造2階建","registered":"1997.11.05(平成9.11.05)","register_no":"06 － 0015","desc":"国道を挟んで，主屋と相対して建つ。２階建で，大きく張り出す軒が特徴的な土蔵であり，街路側の妻に下屋を付している。反対側の建物と相まって白い壁面が連続する景観を作り出しており，道路改修前の敷地の様子を現在に伝える建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000327"},{"id":"00006986","register_sub_id":"101","register_pk":"107968","name":"長沼合名会社仕込蔵","kana":"ながぬまごうめいがいしゃしこみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"山形県","address":"山形県長井市十日町1-652-1他","lat":38.112816,"lng":140.036346,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造平屋建、鉄板葺、建築面積142㎡","structure_material":"土蔵造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"06 － 0103","desc":"敷地の西北隅、中蔵の北に位置する。土蔵造平屋建。南北棟の切妻造鉄板葺置屋根とし、南面に鉄扉をたて、東面と北面に窓を開ける。桁行１９ｍ梁間７．６ｍで、外壁は漆喰塗とする。コンクリート床で、小屋組をトラス組とするなど、中蔵と同様の仕様とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006986"},{"id":"00006985","register_sub_id":"101","register_pk":"107967","name":"長沼合名会社中蔵","kana":"ながぬまごうめいがいしゃなかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"山形県","address":"山形県長井市十日町1-652-1他","lat":38.112675,"lng":140.03627,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、鉄板葺、建築面積117㎡","structure_material":"土蔵造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"06 － 0102","desc":"主屋の西北に東西棟で建つ。桁行１６ｍ梁間７．３ｍの土蔵造２階建、切妻造鉄板葺置屋根とする。内外とも壁は漆喰仕上げで、扉を鉄扉とし、出入口まわりに地元産の石を組む。内部は１階はコンクリート床で貯蔵タンクを置き、２階は板敷で、小屋トラス組とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006985"},{"id":"00006984","register_sub_id":"101","register_pk":"107966","name":"長沼合名会社前蔵","kana":"ながぬまごうめいがいしゃまえぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"山形県","address":"山形県長井市十日町1-652-1他","lat":38.11253793,"lng":140.03681907,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"土蔵造平屋建、鉄板葺、建築面積110㎡","structure_material":"土蔵造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"06 － 0101","desc":"主屋の正面、十日町通りに妻を見せる南北に細長い土蔵。江戸末から明治に建築された３棟の土蔵を、酒造のために繋いで一体としたもので、精米やその貯蔵に使われた。切妻造鉄板葺の置屋根。土蔵造平屋建で、もとは２階床を張った。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006984"},{"id":"00007447","register_sub_id":"101","register_pk":"108429","name":"丸や芳賀醤油店穀蔵","kana":"まるやはがしょうゆてんこくぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"山形県","address":"山形県長井市栄町455","lat":38.10807014,"lng":140.03731586,"geo_status":"db","era":"明治22","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積54㎡","structure_material":"土蔵造2階建","registered":"2009.01.08(平成21.01.08)","register_no":"06 － 0113","desc":"火入れ蔵の西北に、東西棟で建つ。桁行１１ｍ梁間４．６ｍの土蔵造２階建、切妻造鉄板葺の置屋根。外壁は漆喰仕上げで、腰竪板を張り、東面に両開戸を吊り、入口には地元産の石を組む。南面２ヶ所に窓を開け、１、２階通しの掛子塗戸をたてる特徴的仕様を残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007447"},{"id":"00007446","register_sub_id":"101","register_pk":"108428","name":"丸や芳賀醤油店火入れ蔵","kana":"まるやはがしょうゆてんひいれぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"山形県","address":"山形県長井市栄町455","lat":38.108017,"lng":140.037491,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造平屋建、鉄板葺、建築面積53㎡","structure_material":"土蔵造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"06 － 0112","desc":"通りの西に占める敷地のやや奥に、東西棟で建つ。桁行９．３ｍ梁間５．６ｍの土蔵造平屋建、切妻造鉄板葺。外壁は漆喰仕上げで、腰板を張り、西面に戸口を穿つ。南面には４ヶ所に窓を開け、窓枠を丁寧に塗り上げる。内部は一室で、和小屋組とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007446"},{"id":"00008415","register_sub_id":"101","register_pk":"134811","name":"山一醤油店仕込み場","kana":"やまいちしょうゆてんしこみば","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"山形県","address":"山形県長井市あら町2471","lat":38.10161315,"lng":140.03892838,"geo_status":"db","era":"大正9年","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積209㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"06 － 0121","desc":"醤油蔵の後方に軸線をずらして建ち、桁行二七メートル梁間六・五メートル、平屋建で、小屋はトラスを組み、切妻造鉄板葺とする。内部には水路による洗い場や煉瓦窯があり、最奥に土蔵造の味噌室と麹室をつくる。伝統的な醸造工程をよく伝える建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008415"},{"id":"00008414","register_sub_id":"101","register_pk":"134810","name":"山一醤油店醤油蔵","kana":"やまいちしょうゆてんしょうゆぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"山形県","address":"山形県長井市あら町2471","lat":38.10157261,"lng":140.03867084,"geo_status":"db","era":"大正9年","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積207㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"06 － 0120","desc":"店舗事務所棟背面に接続し、桁行二四メートル梁間八・八メートル、土蔵造平屋建、切妻造鉄板葺で、小屋はトラス組とする。外壁は、腰を石積風に仕上げ、掛子塗の扉や鉄扉を吊った窓を連続させて配するなど、重厚な外観をもつ大型の醤油蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008414"},{"id":"00008413","register_sub_id":"101","register_pk":"134809","name":"山一醤油店店舗","kana":"やまいちしょうゆてんてんぽ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"山形県","address":"山形県長井市あら町2471","lat":38.10158454,"lng":140.03825114,"geo_status":"db","era":"大正9年","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造2階一部平屋建、鉄板葺、建築面積248㎡","structure_material":"木造2階一部平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"06 － 0119","desc":"旧街道に西面する短冊形敷地前面に建ち、正面を切妻造平入の店舗棟、後方を両下造の事務所棟とし、間口九・二メートル奥行二六メートル、鉄板葺である。正面に格子を建て、内部の南側を通り土間とするなど、長井の伝統的な商家の形態をよく留めている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008413"},{"id":"00011263","register_sub_id":"101","register_pk":"209099","name":"足尾銅山電話資料館（旧足尾銅山電話交換所）","kana":"あしおどうざんでんわしりょうかん（きゅうあしおどうざんでんわこうかんしょ）","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"栃木県","address":"栃木県日光市足尾町2281","lat":36.642764,"lng":139.450059,"geo_status":"db","era":"昭和26","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積100㎡","structure_material":"木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"09－0231","desc":"足尾銅山には明治一九年に電話が架設され、国内では民間初の私設電話であった。現在の建物は昭和二六年に間藤交換所の機能を移したもので、比較的小規模なものとなる。モルタル塗の外壁に縦長窓を並べ、寄棟造の屋根を架けた文化住宅を思わせる外観を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011263"},{"id":"00007179","register_sub_id":"101","register_pk":"108161","name":"油伝味噌店舗兼主屋","kana":"あぶでんみそてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県栃木市嘉右衛門町438","lat":36.38934348,"lng":139.734146,"geo_status":"db","era":"明治中期／大正期増築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋一部2階建、瓦葺、建築面積170㎡","structure_material":"木造平屋一部2階建","registered":"2008.07.08(平成20.07.08)","register_no":"09 － 0176","desc":"旧例幣使街道に東面して建つ。切妻造桟瓦葺の２階建の東妻面に、寄棟屋根を接する特徴的な屋根構成で、正面には下屋庇を設ける。軒は出桁造で、北半部に出格子窓、南半部に引違建具をたて開放的に扱う。旧街道に面する商家の面影を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007179"},{"id":"00003787","register_sub_id":"101","register_pk":"104777","name":"油伝味噌中蔵","kana":"あぶでんみそなかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"栃木県","address":"栃木県栃木市嘉右衛門町5-26","lat":36.38946423,"lng":139.73382284,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積41㎡","structure_material":"土蔵造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"09 － 0090","desc":"東蔵の西方に東西棟で建つ。桁行５間梁間２間半規模，切妻造，桟瓦葺の平入２階建土蔵で，東蔵と同様に北側に幅２間程の下屋を設ける。北面壁は，西方味噌土蔵の下屋の壁に連続する簓子下見板張の漆喰塗壁で，長大な醸造蔵景観を敷地北面につくりだしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003787"},{"id":"00003786","register_sub_id":"101","register_pk":"104776","name":"油伝味噌東蔵","kana":"あぶでんみそひがしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"栃木県","address":"栃木県栃木市嘉右衛門町5-26","lat":36.38944762,"lng":139.73391375,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積33㎡","structure_material":"土蔵造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"09 － 0089","desc":"文庫蔵の西側に東西棟で建つ。桁行４間梁間２間，切妻造，桟瓦葺の２階建土蔵で，南面に庇を差し掛けて戸前をとるほか，北側に２間幅規模の下屋を設ける。下屋の北面は，東方外塀と連続した凝灰岩造の壁で，敷地北面に特徴的な屋敷構えをつくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003786"},{"id":"00001405","register_sub_id":"101","register_pk":"102395","name":"アンタレススポーツクラブ（旧足利模範撚糸工場）","kana":"あんたれすすぽーつくらぶ（きゅうあしかがもはんねんしこうじょう）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県足利市田中町906-13","lat":36.330544,"lng":139.445053,"geo_status":"db","era":"明治36","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"石造平屋建、瓦葺、建築面積530㎡","structure_material":"石造平屋建","registered":"1999.11.18(平成11.11.18)","register_no":"09 － 0020","desc":"明治政府の輸出絹織物振興の国策によって設立された足利模範撚糸合資会社の洋風工場建築。外壁は大谷石積，控壁付きとし，半円アーチ付きの縦長窓が連なる。鋸屋根の北面に大きな明かり窓を設ける。各地に建設された模範撚糸工場の中で唯一現存するもの。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001405"},{"id":"00010097","register_sub_id":"101","register_pk":"197930","name":"鹿沼市文化活動交流館石蔵（旧帝国繊維石蔵）","kana":"かぬましぶんかかつどうこうりゅうかんいしぐら（きゅうていこくせんいいしぐら）","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"栃木県","address":"栃木県鹿沼市睦町字寺ノ内1956-2","lat":36.569033,"lng":139.752488,"geo_status":"db","era":"大正初期／平成14改修","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"石造平屋建、鋼板葺、建築面積495㎡","structure_material":"石造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"09 － 0215","desc":"製麻業で栄えた当地で、黒川と木島用水が囲む地区に位置する、もと製麻工場の建築。石造平屋建、桁行五五メートルを測る長大な蔵で、下段には近隣で産する深岩石を、上部には大谷石を積み、キングポストトラスの小屋を載せる。製麻産業の最盛期を物語る遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010097"},{"id":"00011264","register_sub_id":"101","register_pk":"209100","name":"旧足尾銅山鉱業事務所付属書庫","kana":"きゅうあしおどうざんこうぎょうじむしょふぞくしょこ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県日光市足尾町2281","lat":36.642357,"lng":139.450186,"geo_status":"db","era":"明治40","year":1965,"year_source":"db","year_min":1965,"year_max":1965,"year_label":null,"structure":"煉瓦造2階建、鉄板葺、建築面積69㎡","structure_material":"煉瓦造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"09－0232","desc":"銅山中枢部の掛水移転にあわせて建設された書庫。煉瓦造二階建とする。イギリス積の外壁で、四隅に白い石材を帯状に配した付柱を設け、両側面と正面中央には妻壁を立ち上げて重厚な外観を持つ。銅山の中心施設の遺構として希少。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011264"},{"id":"00008646","register_sub_id":"101","register_pk":"149367","name":"旧新井製糸所漆喰蔵","kana":"きゅうあらいせいしじょしっくいぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県下都賀郡野木町大字野渡字坪ノ内328-1","lat":36.20670652,"lng":139.70156255,"geo_status":"db","era":"明治中期／平成11年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"煉瓦造及び土蔵造2階建、瓦葺、建築面積42㎡","structure_material":"煉瓦造及び土蔵造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"09 － 0200","desc":"事務室の西に隣接し、東面して建つ。南北棟の切妻造桟瓦葺で、東面に下屋をかける。桁行7.3ｍ梁間4.6ｍ。1階は下野煉化製造会社製煉瓦をイギリス積で1枚厚に積み上げ、2階は土蔵造とする。白漆喰と煉瓦が鮮やかなコントラストを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008646"},{"id":"00008645","register_sub_id":"101","register_pk":"149366","name":"旧新井製糸所事務室","kana":"きゅうあらいせいしじょじむしつ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県下都賀郡野木町大字野渡字坪ノ内328-1","lat":36.20670697,"lng":139.70167195,"geo_status":"db","era":"明治中期／平成3年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積58㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"09 － 0199","desc":"敷地北寄りに建つ。桁行9.1ｍ梁間6.8ｍの木造平屋建。東西棟の東切妻西寄棟造とし、下屋をまわす。桟瓦葺。トコとトコ脇、平書院を構える8畳と、その東の6畳からなり、西・南・東面に縁を付ける。繊細な欄間が飾られる近代和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008645"},{"id":"00008647","register_sub_id":"101","register_pk":"149368","name":"旧新井製糸所煉瓦蔵","kana":"きゅうあらいせいしじょれんがぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県下都賀郡野木町大字野渡字坪ノ内328-1","lat":36.20656336,"lng":139.70154968,"geo_status":"db","era":"明治後期／平成3年・平成14年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"煉瓦造2階建、瓦葺、建築面積69㎡","structure_material":"煉瓦造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"09 － 0201","desc":"漆喰蔵の南に東面して建つ。南北棟の切妻造桟瓦葺、桁行15ｍ梁間4.7ｍ。イギリス積で、中間に水切りを付け、鉢巻は3段の蛇腹とするなど、土蔵造風のデザインもみられる。下野煉化製造会社製の煉瓦で造られ、地域の近代化を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008647"},{"id":"00009434","register_sub_id":"101","register_pk":"194227","name":"杉田酒造大谷石蔵","kana":"すぎたしゅぞうおおやいしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和中","pref":"栃木県","address":"栃木県小山市大字上泉字本沢237","lat":36.31671752,"lng":139.73918852,"geo_status":"db","era":"昭和22年","year":1947,"year_source":"db","year_min":1947,"year_max":1947,"year_label":null,"structure":"石造及び木造平屋建、鉄板葺、建築面積65㎡","structure_material":"石造及び木造平屋建","registered":"2013.03.29(平成25.03.29)","register_no":"09 － 0205","desc":"敷地北側に建ち、石造及び木造平屋建、桁行一○・○メートル梁間六・五三メートル、切妻造鉄板葺である。戦後に米の代用植物であるサツマイモを原料として作成していた焼酎の室の蔵。断熱を考慮した構造が特徴的な、当時の食糧事情を反映した大谷石造の石蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009434"},{"id":"00009431","register_sub_id":"101","register_pk":"194224","name":"杉田酒造仕込蔵","kana":"すぎたしゅぞうしこみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"栃木県","address":"栃木県小山市大字上泉字本沢237","lat":36.31651384,"lng":139.73910762,"geo_status":"db","era":"江戸末期／明治中期移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積167㎡","structure_material":"土蔵造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"09 － 0202","desc":"敷地西側に建ち、土蔵造二階建、桁行一八・二メートル梁間九・一四メートル、寄棟造桟瓦葺である。漆喰塗の外壁に、腰に古色蒼然とした板羽目を張り、外観を整える。二階には大正蔵に向けて連絡路が設置される。架構は概ね創建時の姿を留める仕込蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009431"},{"id":"00009433","register_sub_id":"101","register_pk":"194226","name":"杉田酒造大正蔵","kana":"すぎたしゅぞうたいしょうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"栃木県","address":"栃木県小山市大字上泉字本沢237","lat":36.31664328,"lng":139.73904861,"geo_status":"db","era":"大正3年","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積117㎡","structure_material":"土蔵造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"09 － 0204","desc":"敷地北辺西寄り東西棟で建つ。土蔵造二階建、桁行一四・○メートル梁間八・三四メートル、切妻造桟瓦葺である。外壁は漆喰塗で腰に板羽目を張り、軒部分に緩い勾配をもつ鉢巻を廻す。小屋組は梯子上の二重桁梁として構成するなど、重厚な構造とした土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009433"},{"id":"00009432","register_sub_id":"101","register_pk":"194225","name":"杉田酒造貯蔵蔵","kana":"すぎたしゅぞうちょぞうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"栃木県","address":"栃木県小山市大字上泉字本沢237","lat":36.31659236,"lng":139.7392423,"geo_status":"db","era":"江戸末期／明治6年移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積197㎡","structure_material":"土蔵造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"09 － 0203","desc":"敷地中央北側に建ち、土蔵造二階建、桁行二○・九メートル梁間九・四二メートル、切妻造桟瓦葺である。二階奥に間仕切した約二・五間四方の作業場を設け、かつて杜氏が生活していたと伝えられる。敷地内で最古の建物であり、造酒屋としての歴史を伝える遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009432"},{"id":"00011259","register_sub_id":"101","register_pk":"209094","name":"第一酒造旧桶倉庫","kana":"だいいちしゅぞうきゅうおけそうこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県佐野市田島町488","lat":36.29906,"lng":139.565493,"geo_status":"db","era":"明治中期／昭和後期改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、金属板葺、建築面積183㎡","structure_material":"木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"09－0227","desc":"敷地北東隅に東西棟で建つ。平屋建の倉庫で、北面に下屋を付し、その中ほどに入母屋造、妻入の屋根を架け裏門とし、南面へとつなぐ通路を開く。通路の東側はほぼ正方形の一室とし、西側は台形平面とする。酒蔵とともに造酒屋の景観を特徴づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011259"},{"id":"00011260","register_sub_id":"101","register_pk":"209095","name":"第一酒造旧穀倉","kana":"だいいちしゅぞうきゅうこくぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"栃木県","address":"栃木県佐野市田島町488","lat":36.298282,"lng":139.565447,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積53㎡","structure_material":"木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"09－0228","desc":"通りに面して敷地南辺を画し、表構えを成す長屋門。間口三メートルの表門の東に物置、西に穀倉を設けて、一連の切妻屋根を架ける。もとは大豆等の穀物を納めていたことから穀倉と呼ばれる。外部には下見板張を施し、旧家の格式ある表構えを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011260"},{"id":"00011261","register_sub_id":"101","register_pk":"209097","name":"第一酒造旧米穀蔵","kana":"だいいちしゅぞうきゅうべいこくぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"栃木県","address":"栃木県佐野市田島町488","lat":36.298246,"lng":139.565242,"geo_status":"db","era":"元治元／昭和後期改修","year":1864,"year_source":"db","year_min":1864,"year_max":1864,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積41㎡","structure_material":"土蔵造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"09－0229","desc":"旧穀倉とともに、敷地の南辺を画す土蔵。平屋建で建ちの高い土蔵であるが、当初は二階床があったと伝わる。内部には半割丸太の荷摺木を一定間隔で打ち、米蔵として用いられていた歴史を物語る。漆喰塗の腰を下見板張とする外観で、旧穀倉と一連の表構えをなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011261"},{"id":"00011257","register_sub_id":"101","register_pk":"209092","name":"第一酒造酒蔵","kana":"だいいちしゅぞうさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"栃木県","address":"栃木県佐野市田島町488","lat":36.29898,"lng":139.565151,"geo_status":"db","era":"慶応4頃／昭和後期改修","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積818㎡","structure_material":"土蔵造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"09－0225","desc":"敷地の北西隅に建つ桁行三九メートルの大型土蔵。梁間一一メートルの二階建主体部に、南北に各六メートル幅の下屋を付す構造とする。小屋は身舎柱上を和小屋とし、その間に登梁を架ける。酒造の主要な工程を行う建物で、幕末以来の敷地景観を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011257"},{"id":"00011258","register_sub_id":"101","register_pk":"209093","name":"第一酒造酒蔵事務所","kana":"だいいちしゅぞうさかぐらじむしょ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県佐野市田島町488","lat":36.298794,"lng":139.565367,"geo_status":"db","era":"明治中期／昭和後期改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋一部2階建、瓦葺、建築面積360㎡","structure_material":"木造平屋一部2階建","registered":"2016.11.29(平成28.11.29)","register_no":"09－0226","desc":"酒蔵の南面東端に接続して、南北棟で建つ。切妻造、妻入で、当初は、入口側の南半を帳場として、酒蔵側の北半を釜場として用いていた。二階には杜氏のための居住空間を備える。馬車運送を行った名残として南面中央に大きな開口を設けて土間としている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011258"},{"id":"00001407","register_sub_id":"101","register_pk":"102397","name":"トチセン（旧足利織物）赤レンガサラン工場","kana":"とちせん（きゅうあしかがおりもの）あかれんがさらんこうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県足利市福居町1151-1他","lat":36.306335,"lng":139.457779,"geo_status":"db","era":"大正2～8","year":1913,"year_source":"converted","year_min":1913,"year_max":1913,"year_label":null,"structure":"煉瓦造平屋建、瓦葺、建築面積357㎡","structure_material":"煉瓦造平屋建","registered":"1999.11.18(平成11.11.18)","register_no":"09 － 0022","desc":"東西棟の長大な工場建築。煉瓦造，切妻造で，東妻側に差し掛け屋根の張り出しを設ける。北側面に大きな石材を窓枠とする窓が密に並んでいる点に特色がある。北面東半部では上部にも窓を設けて二階建ての趣を見せているが，上段の窓は後補。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001407"},{"id":"00001406","register_sub_id":"101","register_pk":"102396","name":"トチセン（旧足利織物）赤レンガ捺染工場","kana":"とちせん（きゅうあしかがおりもの）あかれんがなっせんこうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県足利市福居町1151-1他","lat":36.30617212,"lng":139.45732487,"geo_status":"db","era":"大正2～8","year":1913,"year_source":"converted","year_min":1913,"year_max":1913,"year_label":null,"structure":"煉瓦造平屋建、瓦葺、建築面積1587㎡","structure_material":"煉瓦造平屋建","registered":"1999.11.18(平成11.11.18)","register_no":"09 － 0021","desc":"煉瓦造の外壁と木造の内部軸組からなる広大な工場建築で，６連の鋸屋根を架ける。頂部まで立ち登る柱型と重厚な軒蛇腹とで縁取る妻壁の意匠や，出入口・窓の大きな開口部を一石のまぐさ石で支える手法に特色がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001406"},{"id":"00006782","register_sub_id":"101","register_pk":"107764","name":"トチセン（旧足利織物）汽罐室","kana":"とちせん（きゅうあしかがおりもの）きかんしつ","category":"産業2次","subcategory":"建築物","type_guess":"発電・機械","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県足利市福居町字神明地1151-1他","lat":36.30617504,"lng":139.456757,"geo_status":"db","era":"大正前期／昭和16増築","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"煉瓦造平屋建、スレート葺、建築面積239㎡、ボイラー2基付","structure_material":"煉瓦造平屋建","registered":"2008.03.07(平成20.03.07)","register_no":"09 － 0170","desc":"工場敷地の南西隅に位置する煉瓦造平屋建で、波形スレート葺の切妻屋根を２連にかける。妻壁は北棟が山形、増築の南棟が方形である。外壁は煉瓦のイギリス積で柱形が付く。内部にはランカシャーボイラーを２基ずつ設置した。黒色迷彩塗装が残り戦時を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006782"},{"id":"00007000","register_sub_id":"101","register_pk":"107982","name":"西堀酒造煙突","kana":"にしぼりしゅぞうえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県小山市大字栗宮1452","lat":36.286217,"lng":139.780472,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"煉瓦造、高さ14m","structure_material":"煉瓦造","registered":"2008.04.18(平成20.04.18)","register_no":"09 － 0173","desc":"敷地のほぼ中央に位置する煉瓦造の煙突である。基底部は１．９ｍ角、高さは約１４ｍである。煉瓦は下野煉化製造会社の製品と伝え、イギリス積とする。四隅に山形鋼を添え、丸鋼をナット締めして補強している。地域のランドマークとして親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007000"},{"id":"00006998","register_sub_id":"101","register_pk":"107980","name":"西堀酒造仕込蔵","kana":"にしぼりしゅぞうしこみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"栃木県","address":"栃木県小山市大字栗宮1452","lat":36.28595458,"lng":139.78062097,"geo_status":"db","era":"大正中期／平成7改修","year":1919,"year_source":"estimated","year_min":1916,"year_max":1922,"year_label":"大正中期","structure":"土蔵造平屋建、瓦葺、建築面積239㎡","structure_material":"土蔵造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"09 － 0171","desc":"敷地の東寄りに建つ土蔵造平屋建で店舗に改装。桁行２８ｍ梁間５．９ｍの南北棟で、屋根を切妻造桟瓦葺とし、西面に２．８ｍ幅の瓦葺庇をつける。大谷石の切石積基礎上に建ち、外壁は白漆喰塗で、腰を簓子下見板張とする。窓上の鉄板葺庇が外観に陰影を加える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006998"},{"id":"00007001","register_sub_id":"101","register_pk":"107983","name":"西堀酒造長屋門","kana":"にしぼりしゅぞうながやもん","category":"産業2次","subcategory":"建築物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県小山市大字栗宮1452","lat":36.2860251,"lng":139.78083252,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積42㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"09 － 0174","desc":"敷地東寄りに東を正面に建つ木造平屋建で、北に瓶詰場の下屋が接続する。桁行９．１ｍ梁間４．６ｍで、切妻造桟瓦葺とする。中央の２間を門口とし、北に部屋、南に物置を設ける。外壁は真壁造漆喰塗で、腰を簓子下見板張とする。風格ある敷地構えを形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007001"},{"id":"00006999","register_sub_id":"101","register_pk":"107981","name":"西堀酒造瓶詰場","kana":"にしぼりしゅぞうびんづめば","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"栃木県","address":"栃木県小山市大字栗宮1452","lat":36.28612348,"lng":139.78086417,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、瓦葺、建築面積221㎡","structure_material":"土蔵造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"09 － 0172","desc":"敷地の北寄りに建つ土蔵造２階建である。桁行１６ｍ梁間１１ｍの東西棟で、屋根は切妻造桟瓦葺とし、東妻の桟瓦葺下屋が長屋門に接続する。切石の基礎上に建ち、外壁は白漆喰塗で鉢巻をつけ、腰を簓子下見板張とする。東妻２階の窓がアクセントとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006999"},{"id":"00005711","register_sub_id":"101","register_pk":"106699","name":"古河掛水倶楽部旧館","kana":"ふるかわかけみずくらぶきゅうかん","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"栃木県","address":"栃木県日光市足尾町2281","lat":36.642559,"lng":139.450546,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、鉄板葺、建築面積231㎡","structure_material":"木造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"09 － 0158","desc":"新館の北西方に南面して建ち，新館と渡廊下で結ばれる。桁行２１ｍ，梁間７ｍ規模，東西棟，寄棟造，鉄板葺の木造平屋建で，南面西端に正面玄関，中央東寄りに脇玄関を設ける。外観は下見板張の洋風とし，内部は西方を畳敷の大広間，東方を洋室とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005711"},{"id":"00005710","register_sub_id":"101","register_pk":"106698","name":"古河掛水倶楽部新館","kana":"ふるかわかけみずくらぶしんかん","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"栃木県","address":"栃木県日光市足尾町2281","lat":36.6423536,"lng":139.45070488,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造2階一部平屋建、鉄板葺、建築面積476㎡","structure_material":"木造2階一部平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"09 － 0157","desc":"渡良瀬川の右岸段丘上に位置し，川に面した東面は石積の柱を現して懸造り風につくる。桁行１７ｍ，梁間１２ｍ規模，切妻造，鉄板葺の木造２階建で，南に厨房等，西に平屋建の球技室を張り出し，２階をハーフティンバー風にするなど変化に富んだ外観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005710"},{"id":"00006552","register_sub_id":"101","register_pk":"107535","name":"若駒酒造主屋","kana":"わかこましゅぞうしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県小山市大字小薬169-1","lat":36.364044,"lng":139.778244,"geo_status":"db","era":"明治初期／昭和12増築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積333㎡、煙突付","structure_material":"木造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"09 － 0162","desc":"市北西部の田園地帯にある。南面して建つ主屋は木造２階建，寄棟造，桟瓦葺の平入で，前面には水路が流れる。東側と北側の平屋建は増築である。平面は東半が座敷，西半が釜場を兼ねた広い土間とする。南西隅に煙突を備えた雄大な屋根を架け，独特の外観を呈す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006552"},{"id":"00006553","register_sub_id":"101","register_pk":"107536","name":"若駒酒造精米所","kana":"わかこましゅぞうせいまいしょ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県小山市大字小薬169-1","lat":36.36388,"lng":139.778,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積209㎡","structure_material":"木造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"09 － 0163","desc":"東西棟の切妻造，桟瓦葺，木造２階建で，正面の東妻面に庇を設け，南面に降ろした下屋を細工所とする。小屋組は和小屋で，道路側の外壁は押縁下見板張とする。醸造業に欠かせない施設であり，市道で区切られた敷地南辺西端にあって，重厚な屋敷景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006553"},{"id":"00006554","register_sub_id":"101","register_pk":"107537","name":"若駒酒造瓶詰場","kana":"わかこましゅぞうびんづめば","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"栃木県","address":"栃木県小山市大字小薬169-1","lat":36.363976,"lng":139.778061,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積268㎡","structure_material":"木造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"09 － 0164","desc":"主屋の西に建つ。南北棟の切妻造，桟瓦葺，木造２階建で，１階南面の東寄りに出入口を設ける。側廻りは半間毎に柱を立てて堅牢につくり，外壁は押縁下見板張である。１階は瓶詰場と白米置場，中２階及び２階は物置とする。大規模で，醸造業に欠かせない施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006554"},{"id":"00011067","register_sub_id":"101","register_pk":"205174","name":"今井酒造店煙突","kana":"いまいしゅぞうてんえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県太田市鳥山中町746-2","lat":36.314762,"lng":139.348077,"geo_status":"db","era":"明治41／昭和40頃改修","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"煉瓦造、高さ14m","structure_material":"煉瓦造","registered":"2016.08.01(平成28.08.01)","register_no":"10 - 0336","desc":"釜場及び瓶詰場の南に位置し、地下の煙道を介して接続する。基部寸法一・三メートル四方、高さ一三・八メートルの煉瓦造煙突であるが、上部は鋼製に改造されている。煉瓦部分はイギリス積。酒造業に欠かせない施設であり、地域のシンボルとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011067"},{"id":"00011065","register_sub_id":"101","register_pk":"205172","name":"今井酒造店釜場及び瓶詰場","kana":"いまいしゅぞうてんかまばおよびびんづめば","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県太田市鳥山中町746-2","lat":36.314863,"lng":139.348123,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造2階建、瓦葺、建築面積155㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"10 - 0334","desc":"本蔵の東に接して建つ。木造二階建、切妻屋根の妻面に深い庇を設ける。酒造工程の最初（洗米・蒸米）と、最終段階である瓶詰が行われ、内部には釜場がある。また東南角部と小屋裏を画した二階部は蔵人の休憩等に用いられた。妻面に梁組を見せるなど意匠を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011065"},{"id":"00011064","register_sub_id":"101","register_pk":"205171","name":"今井酒造店新蔵","kana":"いまいしゅぞうてんしんぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県太田市鳥山中町746-2","lat":36.314725,"lng":139.347861,"geo_status":"db","era":"明治42／昭和40頃改修","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造2階建、瓦葺、建築面積308㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"10 - 0333","desc":"北寄りを本蔵に接する南北棟の土蔵。西面は一段切り下げ、東面は錣葺状に庇を設け、全体で桁行一〇間、梁間九・五間の広い内部を設けている。西下屋は麹室とし、東下屋区切らずに一連としているが、当初は壁で区切られていた。本蔵とともに酒造の中核をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011064"},{"id":"00011062","register_sub_id":"101","register_pk":"205169","name":"今井酒造店店舗兼主屋","kana":"いまいしゅぞうてんてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県太田市鳥山中町746-2","lat":36.314684,"lng":139.348165,"geo_status":"db","era":"明治前期／明治33移築、平成15改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積223㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"10 - 0331","desc":"敷地中程に建つ。近隣の農家を移築し店舗兼主屋としたもの。木造二階建、桁行一〇間、梁間六・五間の規模で、当初は東寄りに広い土間を設け、西半は田字型の平面を基本としていた。屋根は切妻造桟瓦葺で、各面に庇を設ける。農家を基本とする大規模住宅の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011062"},{"id":"00011066","register_sub_id":"101","register_pk":"205173","name":"今井酒造店文庫蔵","kana":"いまいしゅぞうてんぶんこぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県太田市鳥山中町746-2","lat":36.314703,"lng":139.348013,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積21㎡","structure_material":"土蔵造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"10 - 0335","desc":"店舗兼主屋の西北に建つ桁行三間、梁間二間の二階建土蔵で、屋根は置屋根桟瓦葺。主屋側の東に扉を設け、一階北面と二階南面に両開土戸の窓を開く。壁は内外共漆喰塗で、腰巻き上に水切りを付ける。申請書等多量の記録・書類を納める建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011066"},{"id":"00011063","register_sub_id":"101","register_pk":"205170","name":"今井酒造店本蔵","kana":"いまいしゅぞうてんほんぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県太田市鳥山中町746-2","lat":36.31485,"lng":139.347931,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積254㎡","structure_material":"土蔵造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"10 - 0332","desc":"敷地の北西寄りに位置し、新蔵、釜場及び瓶詰場に接する。桁行一二間梁間五間の大規模な土蔵で、外壁は腰部をスギ下見板張とし、上部は漆喰塗籠。一階は総土間で、二階は一部床を張らず吹き抜けとする。酒母・もろみ造りなど主要機能を担っていた建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011063"},{"id":"00015282","register_sub_id":"101","register_pk":"532406","name":"江原本家大庫（旧朝日町醤油醸造蔵）","kana":"えばらほんけおおぐら（きゅうあさひちょうしょうゆじょうぞうぐら）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県前橋市富士見町赤城山字竜ノ口1825-47他","lat":36.49019722,"lng":139.11594167,"geo_status":"db","era":"明治前期／平成13年移築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積159㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"10 - 0356","desc":"前橋市朝日町から移築した旧醸造蔵。敷地南西に北面して建つ平屋建切妻造妻入桟瓦葺で、正面中央戸口に土戸の大戸を建てる。外壁は白漆喰塗仕上で水切を一段廻らし、腰を黒漆喰塗仕上。内部は一室の土間で、三重梁を架けた豪壮な小屋組を現す桁行長大な土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015282"},{"id":"00009706","register_sub_id":"101","register_pk":"195535","name":"岡直三郎商店大間々工場店舗兼主屋","kana":"おかなおさぶろうしょうてんおおままこうじょうてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県みどり市大間々町大間々1013","lat":36.43392194,"lng":139.27463141,"geo_status":"db","era":"明治中期／明治33頃増築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積216㎡、門及び煙突付","structure_material":"木造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"10 － 0306","desc":"通りに東面して建ち、木造二階建、切妻造桟瓦葺。外壁漆喰塗で、二階正面の左右に横長の格子窓を配し、両端に蛇腹付の袖うだつを設ける。内部は南半を店舗、北半を事務室や座敷等とし、店舗部後方に煉瓦煙突を残す。明治二八年の大火を免れ、往時の面影を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009706"},{"id":"00009707","register_sub_id":"101","register_pk":"195536","name":"岡直三郎商店大間々工場文庫蔵","kana":"おかなおさぶろうしょうてんおおままこうじょうぶんこぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県みどり市大間々町大間々1013","lat":36.43405519,"lng":139.2745743,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積44㎡","structure_material":"土蔵造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"10 － 0307","desc":"主屋の北に、東西棟で建つ。桁行九・四メートル梁間四・六メートル、土蔵造二階建、切妻造桟瓦葺。南面を戸口とし、二階南面と東面に窓を設け、掛子塗の扉を吊る。安山岩切石基礎に建ち、外壁は漆喰塗で水切を廻らす。主屋とともに、良好な街路景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009707"},{"id":"00010103","register_sub_id":"101","register_pk":"197936","name":"金子織物株式会社旧従業員宿舎","kana":"かねこおりものかぶしきがいしゃきゅうじゅうぎょういんしゅくしゃ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"群馬県","address":"群馬県桐生市東久方町2-90","lat":36.419559,"lng":139.34741,"geo_status":"db","era":"昭和前期／昭和27移築","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺、建築面積95㎡","structure_material":"木造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"10 － 0312","desc":"敷地北辺東寄りに建ち、西側に旧染場が接続し、背面壁は通りに面する。木造二階建、切妻造桟瓦葺で、外壁は下見板張とし、南面を広く開口し、北面は庇と格子の付いた横長窓を設ける。東妻壁にはトラス組を現す。織物会社の従業員の生活を伝える施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010103"},{"id":"00010102","register_sub_id":"101","register_pk":"197935","name":"金子織物株式会社旧鋸屋根工場","kana":"かねこおりものかぶしきがいしゃきゅうのこぎりやねこうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和中","pref":"群馬県","address":"群馬県桐生市東久方町2-73-1","lat":36.41934,"lng":139.347348,"geo_status":"db","era":"昭和27","year":1952,"year_source":"db","year_min":1952,"year_max":1952,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積160㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"10 － 0311","desc":"敷地南東側に建つ、切妻三連の鋸屋根の工場建築で、北西の主屋側に切妻造の事務所を附属し、屋根は桟瓦葺とする。周囲の横長窓に庇を付け、小屋組はトラス組で、屋根北面に大きな窓を設けて採光をはかる。織物産業で栄えた桐生市の歴史的景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010102"},{"id":"00010100","register_sub_id":"101","register_pk":"197933","name":"金子家住宅蔵","kana":"かねこけじゅうたくくら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県桐生市東久方町2-73-1他","lat":36.419545,"lng":139.347041,"geo_status":"db","era":"明治20","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積21㎡","structure_material":"土蔵造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"10 － 0309","desc":"南面する主屋の西端に接続して南北棟で建ち、土蔵造二階建、桁行五・六メートル梁間三・八メートル、切妻造桟瓦葺である。外壁漆喰塗で鉢巻を廻らし、東面の座敷側に出入口を開く。上下階の南面に庇付の窓を穿つ。織物会社社主住宅の屋敷構えを構成する土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010100"},{"id":"00010101","register_sub_id":"101","register_pk":"197934","name":"金子家住宅倉庫及び旧染場","kana":"かねこけじゅうたくそうこおよびきゅうそめば","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県桐生市東久方町2-90","lat":36.419636,"lng":139.347198,"geo_status":"db","era":"昭和14／昭和27頃改修","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積46㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"10 － 0310","desc":"敷地北辺に建つ切妻造桟瓦葺で、西側を倉庫、東側を細長い旧染場とし、背面壁は外塀を兼ねる。倉庫は外壁下部に下見板を張り、小屋はトラス組。倉庫は漬物小屋や子供室に使い、旧染場は釜場で湯を沸かし、銘仙織物の糸染めを行った。往時の生活を伝える施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010101"},{"id":"00011059","register_sub_id":"101","register_pk":"205166","name":"旧大竹酒造煉瓦蔵","kana":"きゅうおおたけしゅぞうれんがぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"群馬県","address":"群馬県前橋市三河町一丁目28-23","lat":36.388833,"lng":139.076425,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"煉瓦造2階建、瓦葺、建築面積236㎡","structure_material":"煉瓦造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"10 - 0328","desc":"前橋の中心市街地に残る唯一の酒造蔵。昭和八年に大竹酒造が建物を取得し、四七年まで醸造を行っていた。煉瓦造を主体とするが壁厚は一枚分で内部に柱を二列八本立て、和小屋を組む。外壁は軒蛇腹、破風や柱型の一部に焼過煉瓦を配し、立体感を強調している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011059"},{"id":"00010559","register_sub_id":"101","register_pk":"201133","name":"旧金谷家住宅蔵","kana":"きゅうかなやけじゅうたくくら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県桐生市東久方町1-96-3他","lat":36.420473,"lng":139.346732,"geo_status":"db","era":"明治6年／昭和初期移築","year":1873,"year_source":"db","year_min":1873,"year_max":1873,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"10－0321","desc":"主屋背面の蔵前に接続して建つ二階建の土蔵。南北棟の切妻造桟瓦葺で、大棟の棟積を輪違とし、両端の鬼瓦に影盛りを施す。内部は板床で一階は板壁、二階は漆喰壁で、二階床中央の荷揚げ用の開口に格子を嵌め込む。主屋と並び西面通り側の景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010559"},{"id":"00010558","register_sub_id":"101","register_pk":"201132","name":"旧金谷家住宅主屋","kana":"きゅうかなやけじゅうたくしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県桐生市東久方町1-96-3他","lat":36.420371,"lng":139.346694,"geo_status":"db","era":"昭和6年／昭和52年改修","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積198㎡","structure_material":"木造平屋一部2階建","registered":"2015.08.04(平成27.08.04)","register_no":"10－0320","desc":"織物工場を併設した住宅の主屋で、事務所西に接続して建つ。木造平屋一部二階建桟瓦葺で、内部は西寄りに廊下を矩手に廻した八畳の座敷を二室並べ、東はハーフティンバー風の洋間とする。隣接する洋風の事務所と対比的な和風建築で、桐生らしい佇まいを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010558"},{"id":"00000949","register_sub_id":"101","register_pk":"101939","name":"旧株式会社金芳織物工場事務所","kana":"きゅうかぶしきがいしゃかなよしおりものこうじょうじむしょ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県桐生市東久方町1-1-55","lat":36.4203594,"lng":139.3467779,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造２階建，建築面積71㎡","structure_material":"木造２階建","registered":"1998.12.11(平成10.12.11)","register_no":"10 － 0033","desc":"金谷芳次郎が設立した金芳織物工場の事務所建築。大正８年建造の煉瓦造工場に接続するが，スクラッチタイルの使用が建築年代を明示する。水平線の強調はライト式建築の特徴。角部の丸みや丸窓の意匠に時代の特色がよく表れている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000949"},{"id":"00010560","register_sub_id":"101","register_pk":"201134","name":"旧株式会社金芳織物工場染色場","kana":"きゅうかぶしきがいしゃかなよしおりものこうじょうせんしょくば","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県桐生市東久方町1-96-2他","lat":36.420431,"lng":139.346884,"geo_status":"db","era":"大正8年","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積28㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"10－0322","desc":"事務所の背面に隣接して建つ染色場。梁間の長い切妻造鉄板葺、東西棟の簡素な建物で、小屋をキングポストトラスとし、屋根に天窓を四所開ける。壁面にも要所にガラス窓を付す。鋸屋根工場と並び金芳織物工場創業期の建築として価値があり、桐生の繁栄を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010560"},{"id":"00000950","register_sub_id":"101","register_pk":"101940","name":"旧株式会社金芳織物工場鋸屋根工場","kana":"きゅうかぶしきがいしゃかなよしおりものこうじょうのこぎりやねこうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県桐生市東久方町1-1-55","lat":36.42034862,"lng":139.3469733,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"煉瓦造平屋建，鉄板葺，建築面積298㎡","structure_material":"煉瓦造平屋建","registered":"1998.12.11(平成10.12.11)","register_no":"10 － 0034","desc":"大正８年１２月１４日上棟の織物工場。施工は高崎市の島田組。外周壁を煉瓦造とし，木造で「鋸刃」状の屋根を架けた標準的な工場建築の造りを示す。京都西陣と並ぶ高級織物産地として知られる桐生の繁栄ぶりを今に伝えていることで貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000950"},{"id":"00005248","register_sub_id":"101","register_pk":"106236","name":"旧曽我織物工場","kana":"きゅうそがおりものこうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県桐生市本町一丁目甲225-1","lat":36.418739,"lng":139.343201,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木骨石造平屋建、鉄板葺、建築面積550㎡","structure_material":"木骨石造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"10 － 0152","desc":"桁行８間の石造平屋建で，梁間２０尺の鋸屋根５連をかける。屋根は東西棟で，鉄板葺，アルミサッシュ建具に改修されている。小屋組は木造である。外壁は大谷石の切石整層積である。戸口と窓はまぐさを入れ，両開き鉄扉を吊り込む。西妻に円形の換気窓を開く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005248"},{"id":"00005247","register_sub_id":"101","register_pk":"106235","name":"旧堀祐織物工場（美容室アッシュキリュウ）","kana":"きゅうほりゆうおりものこうじょう（びようしつあっしゅきりゅう）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県桐生市巴町1-1126","lat":36.40955714,"lng":139.33596872,"geo_status":"db","era":"昭和10頃","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"石造平屋建、瓦葺、建築面積207㎡","structure_material":"石造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"10 － 0151","desc":"桁行６間半，梁間１０間の石造平屋建で，３連の鋸屋根をかける工場遺構である。内装，戸口，屋根は転用時に改修された。外壁は大谷石の切石整層積である。窓はまぐさ付き縦長矩形で両開き鉄扉を吊り込む。南面に当初の戸口を残す。建物転用の好事例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005247"},{"id":"00010918","register_sub_id":"101","register_pk":"208889","name":"旧本間酒造酒蔵及び釜屋","kana":"きゅうほんましゅぞうさかぐらおよびかまや","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"群馬県","address":"群馬県前橋市総社町総社字町屋敷南乙1500","lat":36.408424,"lng":139.040215,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建及び木造平屋建、瓦葺、建築面積524㎡","structure_material":"土蔵造2階建及び木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"10-0326","desc":"敷地北寄りに建つ。洗米から仕込みまでの酒造に用いられた。中心となる酒蔵は和小屋を架けた土蔵造二階建で、仕込み等に用いるため上下階とも一室とする。東に釜屋を付属し、南にオロシと呼ばれる下屋を広く張り出す。造酒屋の往時の繁栄を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010918"},{"id":"00010917","register_sub_id":"101","register_pk":"208888","name":"旧本間酒造店舗兼主屋","kana":"きゅうほんましゅぞうてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県前橋市総社町総社字町屋敷南乙1500","lat":36.408405,"lng":139.040568,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造2階建、瓦葺、建築面積232㎡","structure_material":"木造2階建","registered":"2016.02.25(平成28.02.25)","register_no":"10-0325","desc":"旧街道に東面し、入母屋造妻入となる町家。一階は南一間を通り土間とし、東に土間、西に接客用座敷などの床上部を設ける。二階は東と南に廊下を巡らせて居室を並べる。二階の軒はせがい造にして深く出し、表情を付ける。総社宿の町並みに歴史的景観を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010917"},{"id":"00005416","register_sub_id":"101","register_pk":"106404","name":"後藤織物井戸屋形","kana":"ごとうおりものいどやかた","category":"産業2次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"群馬県","address":"群馬県桐生市東一丁目730","lat":36.41119658,"lng":139.3459391,"geo_status":"db","era":"昭和8頃","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造、鉄板葺、面積8.5㎡","structure_material":"木造","registered":"2006.03.27(平成18.03.27)","register_no":"10 － 0165","desc":"主屋北面増築部の西方，奥座敷１０畳の北方に位置し，南北棟で建つ。桁行３．２ｍ，梁間２．６ｍ，切妻造，鉄板葺で，柱を内転びに立て，北・西・南の三方を波形鉄板で囲う。ほぼ中央に河原石積の井戸を掘る。染色のための用水の水源を覆う小屋である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005416"},{"id":"00005420","register_sub_id":"101","register_pk":"106408","name":"後藤織物表門及び板塀","kana":"ごとうおりものおもてもんおよびいたべい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県桐生市東一丁目729-2、730","lat":36.41098765,"lng":139.34597426,"geo_status":"db","era":"大正14頃","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"表門 木造、瓦葺、間口4.5m、板塀 木造、鉄板葺、延長23m","structure_material":"表門 木造","registered":"2006.03.27(平成18.03.27)","register_no":"10 － 0169","desc":"主屋の南方に道路から後退して建つ。門は，間口４．５ｍの中央２．１ｍを門口とした切妻造，桟瓦葺の棟門で，門口には引き分け戸を建て込む。門口の両脇には腰下見板張，上部漆喰塗の袖壁を配し，東に長１１ｍ，西に長１２ｍの板塀を延ばして正面の構えとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005420"},{"id":"00005415","register_sub_id":"101","register_pk":"106403","name":"後藤織物旧釜場","kana":"ごとうおりものきゅうかまば","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"群馬県","address":"群馬県桐生市東一丁目730","lat":36.411072,"lng":139.346161,"geo_status":"db","era":"昭和24","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積56㎡","structure_material":"木造平屋建","registered":"2006.03.27(平成18.03.27)","register_no":"10 － 0164","desc":"主屋北東部に位置する。桁行４間半，梁間３間半，東西棟，切妻造，瓦葺の木造平屋建で，内部中央西寄りに大中小５口の煉瓦造釜を据える。小屋組はキングポストトラスで，棟中央西寄りに越屋根を載せる。外壁は下見板張り。織物工場の主要施設のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005415"},{"id":"00005417","register_sub_id":"101","register_pk":"106405","name":"後藤織物給水塔","kana":"ごとうおりものきゅうすいとう","category":"産業2次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"群馬県","address":"群馬県桐生市東一丁目730","lat":36.41125465,"lng":139.34589056,"geo_status":"db","era":"昭和8頃","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造、高さ5.7m","structure_material":"鉄筋コンクリート造","registered":"2006.03.27(平成18.03.27)","register_no":"10 － 0166","desc":"井戸屋形の北西方に位置し，工場西南隅に接して建つ。一辺３ｍ，高さ５．７ｍで，鉄筋コンクリート造４本柱で架構を造り，上部に直径２ｍ，深さ１ｍの鉄筋コンクリート造貯水槽を載せる。染色のための用水タンクで，工場の近代化の一面を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005417"},{"id":"00005412","register_sub_id":"101","register_pk":"106400","name":"後藤織物工場","kana":"ごとうおりものこうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和中","pref":"群馬県","address":"群馬県桐生市東一丁目730","lat":36.411389,"lng":139.34600577,"geo_status":"db","era":"昭和23／昭和24・25増築","year":1948,"year_source":"db","year_min":1948,"year_max":1948,"year_label":null,"structure":"木造平屋建、瓦葺及び鉄板葺、建築面積720㎡、便所付","structure_material":"木造平屋建","registered":"2006.03.27(平成18.03.27)","register_no":"10 － 0161","desc":"主屋及び奥座敷の北方に東西棟で建つ。主屋寄りの桁行９間，梁間３間，キングポストトラス，切妻屋根の工場棟の北方に，桁行１３間，梁間３間の鋸屋根工場２連を増築する。外装押縁下見板張の木造織物工場で，桐生の機業界の戦後復興を物語る施設のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005412"},{"id":"00005418","register_sub_id":"101","register_pk":"106406","name":"後藤織物倉庫","kana":"ごとうおりものそうこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県桐生市東一丁目730","lat":36.41099394,"lng":139.34608865,"geo_status":"db","era":"大正14頃","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2006.03.27(平成18.03.27)","register_no":"10 － 0167","desc":"主屋の東南方，表門を入って右手に位置し，南北棟で建つ。桁行４間，梁間２間規模，切妻造，桟瓦葺の木造平屋建で，西面北寄りに戸口を開け，東面には下屋を添わす。絹糸の保管庫として建設されたもので，織物工場の主要施設のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005418"},{"id":"00005414","register_sub_id":"101","register_pk":"106402","name":"後藤織物西蔵","kana":"ごとうおりものにしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"群馬県","address":"群馬県桐生市東一丁目730","lat":36.41157226,"lng":139.34603071,"geo_status":"db","era":"昭和11頃","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積64㎡","structure_material":"木造平屋建","registered":"2006.03.27(平成18.03.27)","register_no":"10 － 0163","desc":"工場の北方西寄りに位置し，東蔵と並び建ち，桁行６間，梁間２間と同規模で，南面全面に１間幅の下屋を設け，木造平屋建，鉄板葺とする。内部は１室で，下屋境にも間仕切りを設けない。紋紙の収蔵倉庫であり，織物工場の主要施設のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005414"},{"id":"00005413","register_sub_id":"101","register_pk":"106401","name":"後藤織物東蔵","kana":"ごとうおりものひがしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県桐生市東一丁目730","lat":36.411518,"lng":139.346191,"geo_status":"db","era":"明治前期／大正14頃曳家","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積64㎡","structure_material":"木造2階建","registered":"2006.03.27(平成18.03.27)","register_no":"10 － 0162","desc":"工場の北方東寄りに位置し，東西棟で建つ。桁行６間，梁間２間，切妻造，桟瓦葺の木造２階建で，南面全面に１間幅の下屋を設けて蔵前とし，内部は２室に分ける。工場敷地背面側にあり，外装は押縁下見板張としている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005413"},{"id":"00005419","register_sub_id":"101","register_pk":"106407","name":"後藤織物物置","kana":"ごとうおりものものおき","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"群馬県","address":"群馬県桐生市東一丁目730","lat":36.41128984,"lng":139.34622423,"geo_status":"db","era":"大正14頃","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積55㎡","structure_material":"木造平屋建","registered":"2006.03.27(平成18.03.27)","register_no":"10 － 0168","desc":"工場の東方，敷地東辺に沿って「く」の字形に屈折して建つ。桁行全長１６間，梁間１間規模の南北に細長い平面をもち，鉄板葺の招き屋根を架ける。南半が味噌醤油等の従業員向け食料保管庫とし，北半を薪炭置き場とする。織物工場の施設のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005419"},{"id":"00010108","register_sub_id":"101","register_pk":"197941","name":"小林家住宅（旧小武織物有限会社）石垣","kana":"こばやしけじゅうたく（きゅうこたけおりものゆうげんがいしゃ）いしがき","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"low","period":"昭和中","pref":"群馬県","address":"群馬県桐生市広沢町5字福島1111-9他","lat":36.37841132,"lng":139.35045716,"geo_status":"db","era":"昭和28頃","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"石造、総延長82m","structure_material":"石造","registered":"2014.10.07(平成26.10.07)","register_no":"10 － 0317","desc":"敷地の南面と西面に築かれた石垣で、門の入口では折曲がりに設ける。高さ約一・五メートル、底部幅約一・二メートル、総延長八二メートルに玉石を積み、コンクリートで固めて厚く目地を盛る。台風による水害後に築かれた石垣で、工場や住宅の防災を担う。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010108"},{"id":"00010105","register_sub_id":"101","register_pk":"197938","name":"小林家住宅（旧小武織物有限会社）工場","kana":"こばやしけじゅうたく（きゅうこたけおりものゆうげんがいしゃ）こうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和中","pref":"群馬県","address":"群馬県桐生市広沢町5字福島1111-6他","lat":36.37855,"lng":139.350488,"geo_status":"db","era":"昭和23／昭和29改修","year":1948,"year_source":"db","year_min":1948,"year_max":1948,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積276㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"10 － 0314","desc":"主屋土間部に接続し、東西にのびる工場。南北棟の切妻造建物四棟を並行させた形式で、桟瓦葺とする。外壁は簓子下見板張で、妻壁には下端を尖頭形とした竪板を張詰める。市内で多数を占める鋸屋根とは異なる屋根形式をもつ工場で、桐生の工場建築の一例を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010105"},{"id":"00010104","register_sub_id":"101","register_pk":"197937","name":"小林家住宅（旧小武織物有限会社）主屋","kana":"こばやしけじゅうたく（きゅうこたけおりものゆうげんがいしゃ）しゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県桐生市広沢町5字福島1111-3他","lat":36.378663,"lng":139.350319,"geo_status":"db","era":"昭和6頃／昭和中期改修","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積332㎡","structure_material":"木造平屋一部2階建","registered":"2014.10.07(平成26.10.07)","register_no":"10 － 0313","desc":"敷地西側に東面して建つ。切妻造桟瓦葺で正面中央に入母屋玄関を構え、周囲に下屋を廻らす。外壁は腰に簓子下見板を張り、妻壁は三段の梁組を現す。北半の土間は工場と一体化し、床上部は当初部の四間取の南に座敷を増築する。座敷の造作に古式を残す住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010104"},{"id":"00010106","register_sub_id":"101","register_pk":"197939","name":"小林家住宅（旧小武織物有限会社）倉庫一","kana":"こばやしけじゅうたく（きゅうこたけおりものゆうげんがいしゃ）そうこ１","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和中","pref":"群馬県","address":"群馬県桐生市広沢町5字福島1111-9他","lat":36.378449,"lng":139.350408,"geo_status":"db","era":"昭和36","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"コンクリートブロック造平屋建、瓦葺、建築面積21㎡","structure_material":"コンクリートブロック造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"10 － 0315","desc":"敷地南面東寄りに開く門から西側にのびる石垣上に建つ倉庫。コンクリートブロック造、切妻造桟瓦葺で、西側の下屋に井戸と流し場を設けた。内外壁ともモルタル塗で仕上げ、小屋はトラス組とする。織物の糸の保管や、工場用水と生活用水の確保に使用した建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010106"},{"id":"00010107","register_sub_id":"101","register_pk":"197940","name":"小林家住宅（旧小武織物有限会社）倉庫二","kana":"こばやしけじゅうたく（きゅうこたけおりものゆうげんがいしゃ）そうこ２","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和中","pref":"群馬県","address":"群馬県桐生市広沢町5字福島1111-9他","lat":36.378403,"lng":139.350531,"geo_status":"db","era":"昭和37","year":1962,"year_source":"db","year_min":1962,"year_max":1962,"year_label":null,"structure":"コンクリートブロック造平屋建、瓦葺、建築面積19㎡","structure_material":"コンクリートブロック造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"10 － 0316","desc":"敷地入口の東寄りに、倉庫一と向き合って石垣上に建つ。コンクリートブロック造、切妻造桟瓦葺で、内外壁ともモルタル塗で仕上げる。不整形な平面をもち、小屋は和小屋とする。操業時は織物の紋紙を保管していた倉庫で、織物の生産工程を伝える建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010107"},{"id":"00010109","register_sub_id":"101","register_pk":"197942","name":"小林家住宅（旧小武織物有限会社）塀","kana":"こばやしけじゅうたく（きゅうこたけおりものゆうげんがいしゃ）へい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和中","pref":"群馬県","address":"群馬県桐生市広沢町5字福島1111-9他","lat":36.37848512,"lng":139.35024773,"geo_status":"db","era":"昭和28頃","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造、瓦葺、総延長49m","structure_material":"木造","registered":"2014.10.07(平成26.10.07)","register_no":"10 － 0318","desc":"敷地南面の石垣上を廻る透し板塀で、門の入口では折曲がりに設け、西端は作業員宿舎に接続する。土台上の柱を貫でつなぎ、屋根に雁振瓦を伏せ、高さ約一メートルとする。壁は竪板張目板打で、欄間に横桟一本を入れる。織物工場兼社主宅の屋敷構えを引立てる塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010109"},{"id":"00003811","register_sub_id":"101","register_pk":"104801","name":"正田醤油七号蔵","kana":"しょうだしょうゆななごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県館林市栄町3-1","lat":36.24776962,"lng":139.52585355,"geo_status":"db","era":"明治44","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"土蔵造平屋建、スレート葺、建築面積562㎡","structure_material":"土蔵造平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"10 － 0109","desc":"六号蔵の南方に軸線を揃えて建つ。桁行２０間梁間８間規模，南北棟，切妻造，波形スレート（もと桟瓦）葺の平屋建仕込蔵で，内部は六号蔵と同様のつくりとなるが，間内の柱は２間間隔（六号蔵は４間を基本）に建てる。敷地南部に八号蔵と２連の妻面を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003811"},{"id":"00003812","register_sub_id":"101","register_pk":"104802","name":"正田醤油八号蔵","kana":"しょうだしょうゆはちごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"群馬県","address":"群馬県館林市栄町3-1","lat":36.24821983,"lng":139.52588138,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造平屋建、瓦葺、建築面積1479㎡","structure_material":"木造平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"10 － 0110","desc":"六号蔵及び七号蔵の西方に並び建つ。南北棟，切妻造，桟瓦葺で，桁行５２間と長大。内部は六号蔵と同様で，小屋組もトラスであるが，六号蔵南妻面通り筋と南北両妻面のみ和小屋とする点に特色がある。長大な壁面と屋根が醸造場特有の景観を敷地西面につくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003812"},{"id":"00003810","register_sub_id":"101","register_pk":"104800","name":"正田醤油六号蔵","kana":"しょうだしょうゆろくごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県館林市栄町3-1","lat":36.24825963,"lng":139.52612478,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"土蔵造平屋建、鉄板葺、建築面積857㎡","structure_material":"土蔵造平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"10 － 0108","desc":"敷地西寄りに南北棟で建つ。桁行３０間梁間８間規模の醸造仕込蔵で，内部に柱を２列配した３廊式とし，主廊部の小屋組にはキングポストトラスを採り，他の醸造蔵と異なりこの蔵のみ入母屋造の屋根を架ける。正田醤油拡張期を物語る遺構のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003810"},{"id":"00000428","register_sub_id":"101","register_pk":"101418","name":"分福酒造店舗","kana":"ぶんぶくしゅぞうてんぽ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"群馬県","address":"群馬県館林市仲町2626-1","lat":36.24743469,"lng":139.53047346,"geo_status":"db","era":"江戸時代末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸時代末期","structure":"木造2階建，瓦葺，建築面積61㎡","structure_material":"木造2階建","registered":"1998.01.16(平成10.01.16)","register_no":"10 － 0025","desc":"旧城下の南西部に位置する酒造業を営んだ家の店舗。１階を開放的にして２階を格子にする等，町家の特徴をよく備える。館林城下に現存する数少ない本格的な町家のひとつで，使用されている木材の質も高い。保存状況がよく往時の雰囲気をよく伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000428"},{"id":"00004800","register_sub_id":"101","register_pk":"105790","name":"MAEHARA 20th（旧合名会社飯塚織物工場）","kana":"まえはらとぅえんてぃーす（きゅうごうめいがいしゃいいづかおりものこうじょう）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県桐生市広沢町6-850-5","lat":36.3719678,"lng":139.35071269,"geo_status":"db","era":"昭和7頃","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木骨石造平屋建、スレート葺、建築面積884㎡","structure_material":"木骨石造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"10 － 0126","desc":"鋸屋根の木骨石造で飯塚織物工場として建設。南に向って桁行を減じる台形平面をもち，６連の鋸屋根を架ける。敷地傾斜に従い，北ほど基礎が高い。外壁は大谷石で，柱形を見せ，北辺両端は円柱に造る。西面北寄りにアーチを飾った戸口を設けている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004800"},{"id":"00004930","register_sub_id":"101","register_pk":"105920","name":"無鄰館蔵（旧北川織物工場蔵）","kana":"むりんかんくら（きゅうきたがわおりものこうじょうくら）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県桐生市本町1-5-5","lat":36.41933727,"lng":139.34406776,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積17㎡","structure_material":"土蔵造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"10 － 0133","desc":"事務所の背面に建つ桁行４．８メートル，梁間３．９メートル，切妻造桟瓦葺，南北棟の土蔵造２階建である。妻は大谷石の切妻壁を立上げ，外壁と共にモルタル洗出しで仕上げる。内庭からの景観を特徴づける。設計は文部省技師・山田太市。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004930"},{"id":"00004929","register_sub_id":"101","register_pk":"105919","name":"無鄰館事務所（旧北川織物工場事務所）","kana":"むりんかんじむしょ（きゅうきたがわおりものこうじょうじむしょ）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県桐生市本町1-5-5","lat":36.41929597,"lng":139.34400207,"geo_status":"db","era":"大正5／大正10増築","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積91㎡","structure_material":"木造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"10 － 0132","desc":"工場主屋南東角に取付く切妻造桟瓦葺の木造平屋建である。南を正面とし，西端は工場主屋正面増築部の東端と壁を共有する。現在は外観にモルタル塗のパラペットを立上げるが，当時は工場主屋と一体的に使われ，工場の様子を今日に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004929"},{"id":"00004928","register_sub_id":"101","register_pk":"105918","name":"無鄰館主屋（旧北川織物工場主屋）","kana":"むりんかんしゅおく（きゅうきたがわおりものこうじょうしゅおく）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県桐生市本町1-5-5","lat":36.419449,"lng":139.343842,"geo_status":"db","era":"大正5／大正10増築","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、瓦葺及び鉄板葺、建築面積597㎡","structure_material":"木造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"10 － 0131","desc":"敷地中央西寄に南面して建つ木造の工場。桁行２２メートル，梁間７メートル，東西棟の瓦及び鉄板葺屋根が鋸歯状に２列並び，それぞれの屋根南面に換気口が４つ取付く。西面，背面に増築された鋸屋根と共に，織物の町・桐生市に特徴的な歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004928"},{"id":"00004931","register_sub_id":"101","register_pk":"105921","name":"無鄰館煉瓦塀一（旧北川織物工場女工宿舎煉瓦造外壁）","kana":"むりんかんれんがべいいち（きゅうきたがわおりものこうじょうじょこうしゅくしゃれんがぞうがいへき）","category":"産業2次","subcategory":"その他工作物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県桐生市本町1-5-5","lat":36.41956212,"lng":139.34402134,"geo_status":"db","era":"大正5頃","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"煉瓦造、延長18m","structure_material":"煉瓦造","registered":"2005.11.10(平成17.11.10)","register_no":"10 － 0134","desc":"敷地北側境界に沿って建つ高さ６．２メートル，延長１８．３メートルの煉瓦塀。防火を目的に，工場女工宿舎の北側外壁として建てられた。煉瓦をイギリス積で積上げ，現在は鉄骨で補強する。工場主屋の鋸屋根と共に地域の歴史的景観を特徴づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004931"},{"id":"00004932","register_sub_id":"101","register_pk":"105922","name":"無鄰館煉瓦塀二（旧北川織物工場煉瓦塀）","kana":"むりんかんれんがべいに（きゅうきたがわおりものこうじょうれんがべい）","category":"産業2次","subcategory":"その他工作物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県桐生市本町1-5-5","lat":36.41968202,"lng":139.34384679,"geo_status":"db","era":"大正5頃","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"煉瓦造、総延長33m","structure_material":"煉瓦造","registered":"2005.11.10(平成17.11.10)","register_no":"10 － 0135","desc":"女工宿舎煉瓦造外壁の両端から敷地北西隅及び北東隅まで延びる煉瓦塀。高さ２．４メートルで，東側延長１４．０メートル，西側延長１９．２メートルになる。煉瓦の寸法ならびに積方は女工宿舎煉瓦外壁と同じイギリス積で，一連の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004932"},{"id":"00005575","register_sub_id":"101","register_pk":"106563","name":"森秀織物旧釜場","kana":"もりひでおりものきゅうかまば","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"群馬県","address":"群馬県桐生市東4-2-24","lat":36.410122,"lng":139.344727,"geo_status":"db","era":"大正13頃","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積127㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"10 － 0181","desc":"旧整経場の南側に接して建つ。桁行１６．０ｍ，梁間７．５ｍの規模で，木造平屋建，切妻造，桟瓦葺とする。外壁は旧整経場と同じ形式とする。屋根に換気のための越屋根を載せ，切妻造の瓦屋根とする。往時の建物用途の特徴を残し，織物工場の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005575"},{"id":"00005569","register_sub_id":"101","register_pk":"106557","name":"森秀織物旧寄宿舎一（製品加工場）","kana":"もりひでおりものきゅうきしゅくしゃいち（せいひんかこうじょう）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県桐生市東4-2-24","lat":36.41042918,"lng":139.34489097,"geo_status":"db","era":"大正13頃","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積57㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"10 － 0175","desc":"旧物置の北側に建つ。桁行４間半，梁間３間半の規模で，木造平屋建，入母屋造，桟瓦葺とする。東西に１０畳間２室を並べ，西側を押入とする。南側と西側をかつては廊下としていた。切妻造の玄関を南西隅に置き，工場敷地内の居住施設の外観を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005569"},{"id":"00005570","register_sub_id":"101","register_pk":"106558","name":"森秀織物旧寄宿舎二","kana":"もりひでおりものきゅうきしゅくしゃに","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"群馬県","address":"群馬県桐生市東4-2-24","lat":36.41064403,"lng":139.34484208,"geo_status":"db","era":"大正13頃／昭和56曳家","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積62㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"10 － 0176","desc":"敷地北東隅に建つ。桁行６．５ｍ，梁間７．５ｍの規模で，木造平屋建，入母屋造，桟瓦葺とする。南側を旧撚糸場に接続し，それ以外の面には下屋が付く。北側以外は窓等の開口部を付けていたが，現在は西側のみに戸口を開く。少なくなった旧寄宿舎の遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005570"},{"id":"00005567","register_sub_id":"101","register_pk":"106555","name":"森秀織物旧現場事務所（経糸整経場）","kana":"もりひでおりものきゅうげんばじむしょ（たていとせいけいじょう）","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県桐生市東4-2-24","lat":36.41005961,"lng":139.34496995,"geo_status":"db","era":"大正13頃","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積83㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"10 － 0173","desc":"敷地南東隅の工場の北側に建つ。桁行９．５ｍ，梁間８．５ｍの規模で，木造平屋建，切妻造，桟瓦葺とする。小屋組をトラスとし，東側に下屋を出しボイラー室としていた。真壁構造とするが，外壁一部に鉄板を張る。西面及び南面にガラス戸及び窓を開く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005567"},{"id":"00005573","register_sub_id":"101","register_pk":"106561","name":"森秀織物旧工場","kana":"もりひでおりものきゅうこうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和中","pref":"群馬県","address":"群馬県桐生市東4-2-24","lat":36.41031972,"lng":139.34471592,"geo_status":"db","era":"昭和21／昭和27頃増築","year":1946,"year_source":"db","year_min":1946,"year_max":1946,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積582㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"10 － 0179","desc":"敷地の西辺に近接して，南北のほぼ中央に建つ。桁行１６ｍ，梁行２３ｍの規模で，木造平屋建，鉄板葺，３連の鋸屋根の形式で，南側が最も古い。小屋組はトラス形式であるが，桁行中央に柱を立てて補強する。桐生の織物工場の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005573"},{"id":"00005574","register_sub_id":"101","register_pk":"106562","name":"森秀織物旧整経場","kana":"もりひでおりものきゅうせいけいじょう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"群馬県","address":"群馬県桐生市東4-2-24","lat":36.410206,"lng":139.344711,"geo_status":"db","era":"大正13頃","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積135㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"10 － 0180","desc":"旧工場の南側に接して建つ。桁行１６．０ｍ，梁間８．５ｍの規模で，木造平屋建，桟瓦葺とする。東西端部を切妻造とし，中央部を鋸屋根の形式とする。外壁は東面を竪板張り，西面を横板張りとする。妻面の竪板張りは下端を鋸歯状に切揃え意匠上の工夫をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005574"},{"id":"00005572","register_sub_id":"101","register_pk":"106560","name":"森秀織物旧土蔵","kana":"もりひでおりものきゅうどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県桐生市東4-2-24","lat":36.410557,"lng":139.34465605,"geo_status":"db","era":"大正13頃","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、瓦葺、建築面積33㎡","structure_material":"木造2階建","registered":"2006.08.03(平成18.08.03)","register_no":"10 － 0178","desc":"敷地の西辺に近接して，やや北方に南北棟で建つ。桁行５間，梁間２間の規模で，木造２階建，切妻造，桟瓦葺とする。東面は１階中央に戸口を開き，１，２階面に左右対称に窓を開く。南北面の中央にも窓を開く。中規模の土蔵で，工場の景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005572"},{"id":"00005571","register_sub_id":"101","register_pk":"106559","name":"森秀織物旧撚糸場","kana":"もりひでおりものきゅうねんしじょう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"群馬県","address":"群馬県桐生市東4-2-24","lat":36.410576,"lng":139.344864,"geo_status":"db","era":"大正13頃","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積127㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"10 － 0177","desc":"敷地北側に，旧寄宿舎二の南側に建つ。桁行１６．９ｍ，梁間７．５ｍの規模で，木造平屋建，切妻造，桟瓦葺で，小屋組はトラス組とする。内壁を漆喰塗，外壁を下見板張とし，西面に木製の格子窓を開き，その両側に戸口を開く。工場の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005571"},{"id":"00005568","register_sub_id":"101","register_pk":"106556","name":"森秀織物旧物置（八丁撚糸場）","kana":"もりひでおりものきゅうものおき（はっちょうねんしじょう）","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"群馬県","address":"群馬県桐生市東4-2-24","lat":36.410213,"lng":139.34494303,"geo_status":"db","era":"大正13頃","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積53㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"10 － 0174","desc":"敷地中央東寄りに建ち，桁行１０．８ｍ，梁間３．３ｍの建物と桁行６．６ｍ，梁間３．０ｍの建物がやや屈曲し，連続して建つ。共に木造平屋建，切妻造，桟瓦葺。小屋組を和小屋とし，東壁をＲＣ造とする。ほぼ創建時に紋紙を収蔵する物置として建設された。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005568"},{"id":"00005566","register_sub_id":"101","register_pk":"106554","name":"森秀織物工場","kana":"もりひでおりものこうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県桐生市東4-2-24","lat":36.40980415,"lng":139.34494908,"geo_status":"db","era":"大正13頃","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積208㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"10 － 0172","desc":"南北に縦長の敷地の南東隅に建つ。桁行９ｍ，梁行２５ｍの規模で，木造平屋建，鉄板葺，３連の鋸屋根の形式とする。小屋組は木造トラスで，外壁は南側に元のモルタル塗が残るが，他は鉄板張りとなっている。鋸屋根を残し，桐生の織物工場の景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005566"},{"id":"00016360","register_sub_id":"101","register_pk":"536427","name":"アトリエあずき倉庫（旧青木製餡工場倉庫）","kana":"あとりえあずきそうこ（きゅうあおきせいあんこうじょうそうこ）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和中","pref":"埼玉県","address":"埼玉県さいたま市浦和区岸町七丁目125-1他","lat":35.8544,"lng":139.65123611,"geo_status":"db","era":"昭和26年／昭和50年・令和5年改修","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造2階建、瓦葺、建築面積146㎡","structure_material":"木造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"11 - 0238","desc":"ＪＲ浦和駅西方に位置する旧製餡工場の小豆倉庫。敷地中央に位置する切妻造妻入桟瓦葺の東西棟で、西に戸口を開け下屋を付す。外壁モルタル仕上。内部の東が旧倉庫で吹抜上部に洋小屋を現す。搬出入用貨車のレール敷を残し、往時の様相を留める小豆用倉庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016360"},{"id":"00011873","register_sub_id":"101","register_pk":"211149","name":"内木酒造店舗兼主屋","kana":"うちきしゅぞうてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県さいたま市桜区西堀六丁目905-1","lat":35.85379,"lng":139.629203,"geo_status":"db","era":"明治6年／平成20年改修","year":1873,"year_source":"db","year_min":1873,"year_max":1873,"year_label":null,"structure":"木造2階建、瓦葺、建築面積172㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"11-169","desc":"荒川左岸付近に構えた敷地中央に南面する。桁行一〇間、梁間七間で、寄棟造、桟瓦葺とし、下屋庇を廻らし正面には玄関を張出す。内部は、西半を広い土間とし、床上部は二列六室で、一〇畳奥の間は付書院を設け丁寧な造り。重厚な表構えを持つ明治初期の商家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011873"},{"id":"00011874","register_sub_id":"101","register_pk":"211150","name":"内木酒造離れ","kana":"うちきしゅぞうはなれ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"埼玉県","address":"埼玉県さいたま市桜区西堀六丁目905-1","lat":35.85374,"lng":139.629369,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積40㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"11-170","desc":"店舗兼主屋の南東に接続する。入母屋造、桟瓦葺で、銅板葺の下屋庇を廻らす。内部は六畳と八畳を並べ、南西に矩折れに縁を廻らす。八畳は平書院を付け、欄間彫刻に凝った意匠を見せる。瀟洒な造りの離れであり、敷地内の景観を良好に形作る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011874"},{"id":"00007876","register_sub_id":"101","register_pk":"108856","name":"岸本家住宅主屋","kana":"きしもとけじゅうたくしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"埼玉県","address":"埼玉県幸手市中2-6249-1他","lat":36.07272513,"lng":139.71846628,"geo_status":"db","era":"江戸末期／昭和後期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積129㎡","structure_material":"木造平屋建","registered":"2009.11.02(平成21.11.02)","register_no":"11-0126","desc":"旧日光街道に西面する。木造つし２階建、桟瓦葺。正面切妻造、背面寄棟造とする主体部の正面に、寄棟造屋根の平側半部のような下屋を付ける。下屋を店舗とし、主体部境には土戸構えを残す。ひときわ目をひく特異な外観で、往時の幸手宿の賑わいが偲ばれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007876"},{"id":"00002521","register_sub_id":"101","register_pk":"103511","name":"旧石川組製糸西洋館別館","kana":"きゅういしかわぐみせいしせいようかんべっかん","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"埼玉県","address":"埼玉県入間市河原町13-13","lat":35.844646,"lng":139.388947,"geo_status":"db","era":"大正10頃","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積149㎡","structure_material":"木造平屋建","registered":"2001.11.20(平成13.11.20)","register_no":"11 － 0038","desc":"石川組製糸は明治から昭和にかけて操業した県内屈指の製糸会社。北が正面の西洋館の東側に，少し遅れて建てられたという。木造平屋建，中廊下式の平面で，北面と南面に各室を配する。外観は軸組をあらわして壁を化粧煉瓦張とし，本館と調和が図られている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002521"},{"id":"00002520","register_sub_id":"101","register_pk":"103510","name":"旧石川組製糸西洋館本館","kana":"きゅういしかわぐみせいしせいようかんほんかん","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"埼玉県","address":"埼玉県入間市河原町13-13","lat":35.84453047,"lng":139.38881098,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造2階建、瓦葺一部銅板葺、建築面積301㎡","structure_material":"木造2階建","registered":"2001.11.20(平成13.11.20)","register_no":"11 － 0037","desc":"石川組製糸がアメリカの貿易商をもてなすため，設計を室岡惣七として建設した迎賓施設。木造２階建で，内部は各室毎に変化を持たせ，天井から造作まで丁寧なつくりになる。セピア色の化粧煉瓦張とした端正な外観は，当地域の近代の景観を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002520"},{"id":"00006789","register_sub_id":"101","register_pk":"107771","name":"旧鏡山酒造昭和蔵","kana":"きゅうかがみやましゅぞうしょうわぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"埼玉県","address":"埼玉県川越市新富町1-10-1","lat":35.9161229,"lng":139.483887,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積231㎡","structure_material":"土蔵造2階建","registered":"2008.03.07(平成20.03.07)","register_no":"11 － 0115","desc":"大正蔵の東南に東西棟で建つ。桁行２５ｍ梁間９．１ｍの切妻造桟瓦葺２階建。外壁は漆喰仕上げ腰モルタル塗とし、水切りを妻側に３段、平側に２段設け、折釘を等間隔に配する。内部は梁間中央に太い通し柱を３間ごとに建て、２階では豪壮な和小屋組を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006789"},{"id":"00006788","register_sub_id":"101","register_pk":"107770","name":"旧鏡山酒造大正蔵","kana":"きゅうかがみやましゅぞうたいしょうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"埼玉県","address":"埼玉県川越市新富町1-10-1","lat":35.916248,"lng":139.483688,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"土蔵造2階一部平屋建、瓦葺、建築面積304㎡","structure_material":"土蔵造2階一部平屋建","registered":"2008.03.07(平成20.03.07)","register_no":"11 － 0114","desc":"明治蔵の東に東西棟で建つ。切妻造桟瓦葺で棟高い上屋に、規模の大きな下屋が南北に取り付き、桁行２２ｍ梁間１４ｍ規模に及ぶ。外壁は漆喰仕上げ、腰下見板張で、上屋南北面を真壁造とし、軒まわりに木部を表すなど、大規模ながら軽快な印象を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006788"},{"id":"00006787","register_sub_id":"101","register_pk":"107769","name":"旧鏡山酒造明治蔵","kana":"きゅうかがみやましゅぞうめいじぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"埼玉県","address":"埼玉県川越市新富町1-10-1","lat":35.916248,"lng":139.483429,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階一部平屋建、瓦葺、建築面積418㎡","structure_material":"土蔵造2階一部平屋建","registered":"2008.03.07(平成20.03.07)","register_no":"11 － 0113","desc":"西面する敷地の西寄り、通り沿いに建つ。南北棟の切妻造妻入桟瓦葺で、東・西・北面に深い下屋をまわし、桁行２１ｍ梁間２０ｍ規模とする。外壁は漆喰仕上げで、腰まわりを下見板張とする。内部は真壁造。南正面の大きな妻壁が重厚で落ち着きある外観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006787"},{"id":"00013689","register_sub_id":"101","register_pk":"505203","name":"旧玉成舎石蔵","kana":"きゅうぎょくせいしゃいしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和中","pref":"埼玉県","address":"埼玉県比企郡小川町大字小川字町裏197-4","lat":36.05316389,"lng":139.26143889,"geo_status":"db","era":"昭和36年／平成30年改修","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"石造2階建、瓦葺、建築面積41㎡","structure_material":"石造2階建","registered":"2021.02.26(令和3.02.26)","register_no":"11 － 201","desc":"主屋西に渡廊下で接続する。桁行八メートル梁間五メートルの石造二階建切妻造桟瓦葺。大谷石積を化粧で現し、東面の開口は重厚なスチール製の開き戸とし意匠上のポイントとなる。内部は一部吹抜で小屋組は木造キングポストトラス。地域の歴史的景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013689"},{"id":"00013688","register_sub_id":"101","register_pk":"505201","name":"旧玉成舎主屋","kana":"きゅうぎょくせいしゃおもや","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県比企郡小川町大字小川字町裏197-4","lat":36.05309722,"lng":139.26155833,"geo_status":"db","era":"明治21年／昭和6年移築改修、平成30年改修","year":1888,"year_source":"db","year_min":1888,"year_max":1888,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積90㎡","structure_material":"木造2階建","registered":"2021.02.26(令和3.02.26)","register_no":"11 － 200","desc":"二階建入母屋造鉄板葺で南面して建つ。明治中期の建築としては二階の建ちが高く、南縁にガラス戸を建て手摺を付す。内部は東を土間、西を二列四室としたが飲食店に改装した。二階は廊下を挟んで四室配する。もと養蚕生育法の伝習館として歴史的に重要である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013688"},{"id":"00012875","register_sub_id":"101","register_pk":"367983","name":"旧強谷織物工場","kana":"きゅうすねやおりものこうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県秩父市山田字上西新木1660-1他","lat":36.00861944,"lng":139.11141667,"geo_status":"db","era":"昭和5年／昭和中期改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、瓦葺及び金属板葺、建築面積443㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"11 － 189","desc":"市街地東北方にある旧絹織工場。木造平屋建、四連の鋸屋根桟瓦葺、屋根北面は鉄板葺で、天窓を設ける。内部は一空間で、西南北三面に出入口を設け、各棟通りの三間毎に柱を立てる。外壁下見板張、トラス小屋組。絹産業で栄えた近代秩父の様相を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012875"},{"id":"00012700","register_sub_id":"101","register_pk":"367603","name":"旧森龍織物工場","kana":"きゅうもりりゅうおりものこうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"埼玉県","address":"埼玉県川口市大字安行領根岸字台2219","lat":35.84291278,"lng":139.71623278,"geo_status":"db","era":"大正9年","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積310㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"11 － 186","desc":"敷地前方に建つ。木造平屋建の鉄板葺で、東西棟の鋸屋根4棟を連ねる。南1棟を倉庫、北3棟を工場にあて、中央2棟の西面に出入口を設ける。内部は棟通りに柱を三間毎に立て、小屋はトラスとする。主屋とともに近代川口の工場制手工業の様相を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012700"},{"id":"00012699","register_sub_id":"101","register_pk":"367602","name":"旧森龍織物主屋","kana":"きゅうもりりゅうおりものしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"埼玉県","address":"埼玉県川口市大字安行領根岸字台2219","lat":35.84291278,"lng":139.71623278,"geo_status":"db","era":"大正13年","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積159㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"11 － 185","desc":"市北部の工場併設住宅。主屋は敷地後方に南面して建つ寄棟造銅板葺の平屋建で、四面に下屋を付す。東に土間、西に2列4室を配して南西二面に縁を廻し、西列奧に座敷を設ける。伝統民家の形式を継承し、近代に発展した川口の工場制手工業の様相を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012699"},{"id":"00014567","register_sub_id":"101","register_pk":"515109","name":"都築家糀屋蔵","kana":"つづきけこうじやくら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"埼玉県","address":"埼玉県越谷市越ヶ谷本町4696-1","lat":35.89455278,"lng":139.78448333,"geo_status":"db","era":"昭和前期／令和2年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"鉄筋コンクリート造2階建、銅板葺、建築面積43㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"11 - 0221","desc":"日光街道越ヶ谷宿の味噌醸造業商家の土蔵風鉄筋コンクリート造倉庫。切妻造平入銅板瓦棒葺、外壁は砂利洗出仕上。各階内壁板張、天井漆喰仕上。南面に四箇所開口を設けて掛子塗形鉄扉を吊り、一階東側が戸口で他は窓とし、戸口扉はダイヤル錠で堅牢な金庫風。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014567"},{"id":"00011876","register_sub_id":"101","register_pk":"211052","name":"飯能織物協同組合事務所棟","kana":"はんのうおりものきょうどうくみあいじむしょとう","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"大正","pref":"埼玉県","address":"埼玉県飯能市仲町（元原町分）31","lat":35.853718,"lng":139.318534,"geo_status":"db","era":"大正11年","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造2階建、瓦葺、建築面積221㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"11-172","desc":"飯能の経済を支えた織物業の組合事務所。和洋折衷の意匠でまとめる木造二階建で、屋根は寄棟造桟瓦葺、外壁下見板張。小屋はトラス。一階廊下の漆喰内壁の鏝絵、二階大広間天井は小幅の折上天井で中央部に起りを持たせるなど、細部意匠にも特色がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011876"},{"id":"00004113","register_sub_id":"101","register_pk":"105103","name":"亀屋商事（旧飯島製糸）煉瓦倉庫","kana":"かめやしょうじ（きゅういいじませいし）れんがそうこ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県古河市東1-15-11","lat":36.19737059,"lng":139.71262386,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"煉瓦造平屋建、瓦葺一部亜鉛葺、建築面積192㎡","structure_material":"煉瓦造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"08 － 0127","desc":"県道を隔てた向かいの敷地に南北棟で建つ。桁行１５間梁間３間規模の長大な煉瓦造２階建倉庫で，壁は１枚半厚のイギリス積，屋根は切妻造，桟瓦葺とする。１階の南北両妻壁を東方に延ばして下屋庇を架け，２戸口を設ける。製糸業の繁栄振りを物語る遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004113"},{"id":"00011446","register_sub_id":"101","register_pk":"210415","name":"旧大塚酒造店舗兼主屋","kana":"きゅうおおつかしゅぞうてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県坂東市岩井3351-2","lat":36.050288,"lng":139.885223,"geo_status":"db","era":"明治中期／平成28年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積176㎡","structure_material":"木造2階建","registered":"2017.05.02(平成29.05.02)","register_no":"08-0297","desc":"敷地西北方に建つ。桁行一五メートル、梁間一○メートルの規模で、屋根は寄棟造桟瓦葺。整形四間取り平面を基本とするが、東南角に台所を突出させ、座敷背面に廊下を廻らすなど近代的な様相を示す。岩井中心地のにぎわいを今に伝える建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011446"},{"id":"00011447","register_sub_id":"101","register_pk":"210416","name":"旧大塚酒造本蔵","kana":"きゅうおおつかしゅぞうほんぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県坂東市岩井3351-2","lat":36.050576,"lng":139.885687,"geo_status":"db","era":"明治28年／平成28年改修","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"木造2階建、瓦葺、建築面積795㎡","structure_material":"木造2階建","registered":"2017.05.02(平成29.05.02)","register_no":"08-0298","desc":"切妻造桟瓦葺で、桁行一七間梁間六間の身舎の三方に三間幅の下屋が取り付き、建築面積七九〇平方メートル余を誇る大規模醸造蔵。身舎部分は全て二階建で和小屋を組み、中央二列の柱は三〇センチ角の太い柱を用いて大空間を支える。地域の歴史を今に伝える建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011447"},{"id":"00014231","register_sub_id":"101","register_pk":"509621","name":"旧岡山酒造養浩園喜雨亭","kana":"きゅうおかやましゅぞうようこうえんきうてい","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県常陸大宮市高部字宿3970","lat":36.66263333,"lng":140.303275,"geo_status":"db","era":"明治中期／平成7年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造3階建、銅板葺、建築面積50㎡","structure_material":"木造3階建","registered":"2022.06.29(令和4.06.29)","register_no":"08 - 0315","desc":"常陸太田と那須を結ぶ街道の高部集落に所在する木造三階建座敷棟。入母屋造で当初は木羽葺。庭に面する南に入口を開く。二階に床付き座敷を構え書画を飾り接客に用いる。三階は大きく逓減させて壁面に看板と色ガラスを嵌めて広告に用い、目を引く建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014231"},{"id":"00002209","register_sub_id":"101","register_pk":"103199","name":"小田部鋳造北土蔵","kana":"こたべちゅうぞうきたどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町田45","lat":36.27383,"lng":140.096466,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造平屋一部2階建、瓦葺、建築面積169㎡","structure_material":"土蔵造平屋一部2階建","registered":"2001.08.28(平成13.08.28)","register_no":"08 － 0057","desc":"主屋の東方に位置する。桁行１３間，梁行３間の長い南北棟，切妻造，桟瓦葺土蔵で，東側１間通りは下屋部とし，西側前面に１間幅の庇を架けて蔵前を造る。内部は北方３間半を物置，南方９間半分を荷蔵とし，荷蔵には２箇所の戸口を西面に開ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002209"},{"id":"00002746","register_sub_id":"101","register_pk":"103736","name":"関根家住宅店舗","kana":"せきねけじゅうたくてんぽ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁390","lat":36.27923729,"lng":140.10153602,"geo_status":"db","era":"明治8","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"木造2階建、瓦葺、建築面積46㎡","structure_material":"木造2階建","registered":"2002.06.25(平成14.06.25)","register_no":"08 － 0060","desc":"真壁町の市街地北寄にあり，明治８年の建設と伝える。通りに面して建つ店舗は，木造２階建，切妻造・桟瓦葺，平入の形式で，通り側に半間幅の下屋庇を設けている。１階はＬ字型土間と帳場からなり，開放的な下屋部分と相俟って商家らしい構えをよく残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002746"},{"id":"00013677","register_sub_id":"101","register_pk":"505179","name":"立川醤油店店舗及び主屋","kana":"たちかわしょうゆてんてんぽおよびおもや","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"茨城県","address":"茨城県常陸太田市西二町字西二西2177他","lat":36.53914722,"lng":140.52261389,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積269㎡","structure_material":"木造2階建","registered":"2021.02.26(令和3.02.26)","register_no":"08 － 314","desc":"太田城址の南に位置。通りに東面して店舗を構え、背後に主屋が接する。店舗はつし二階建切妻造桟瓦葺で正面に下屋を通し、一階南半を土間に板間を張出した店とする。主屋は二階建切妻造桟瓦葺の主体部の南北に下屋を付す。間口の広い店舗が通りの景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013677"},{"id":"00004911","register_sub_id":"101","register_pk":"105901","name":"府中誉釜場","kana":"ふちゅうほまれかまば","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県石岡市国府5-9-32","lat":36.18506178,"lng":140.27506986,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造平屋建、瓦葺、建築面積269㎡","structure_material":"土蔵造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"08 － 0199","desc":"仕込蔵の東側に位置する桁行１８ｍ，梁間１５ｍ規模の平屋建の土蔵。和小屋で，入母屋造とし，棟の南寄りに越屋根を付ける。平側の外装は押縁下見板張で，妻壁と内壁には漆喰を塗り込める。仕込蔵と同じく，創業後間もなくして整備されたと伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004911"},{"id":"00004206","register_sub_id":"101","register_pk":"105196","name":"府中誉穀蔵","kana":"ふちゅうほまれこくぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"茨城県","address":"茨城県石岡市国府5-9-32","lat":36.18549872,"lng":140.27518897,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木骨コンクリート造2階建、瓦葺、建築面積141㎡","structure_material":"木骨コンクリート造2階建","registered":"2004.07.23(平成16.07.23)","register_no":"08 － 0139","desc":"主屋の東南方に位置し南北棟で建つ。桁行８間梁間４間規模，切妻造，桟瓦葺の木骨コンクリート造２階建酒米蔵で，西面全面に８尺幅で下屋庇を差し掛ける。外部は人造石洗い出し仕上げで，石目地を切る。昭和４年の大火後の構法を伝えるものとして貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004206"},{"id":"00004910","register_sub_id":"101","register_pk":"105900","name":"府中誉仕込蔵","kana":"ふちゅうほまれしこみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県石岡市国府5-9-32","lat":36.18522225,"lng":140.27482809,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積950㎡","structure_material":"土蔵造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"08 － 0198","desc":"南北に細長い敷地のほぼ中央に建つ。桁行４７．５ｍ，梁間２０ｍ規模の土蔵造２階建で，小屋組は和小屋とする。南側は切妻造，北側は入母屋造で妻面を押縁下見板張とし，両妻面に窓を開く。屋敷の中央に位置する規模の大きな酒造工場施設である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004910"},{"id":"00004912","register_sub_id":"101","register_pk":"105902","name":"府中誉舂屋","kana":"ふちゅうほまれつきや","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県石岡市国府5-9-32","lat":36.18532435,"lng":140.27515018,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造平屋建、瓦葺、建築面積132㎡","structure_material":"土蔵造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"08 － 0200","desc":"敷地中央の東端に建つ，米舂き精米用施設。桁行１８ｍ，梁間７．３ｍ規模の土蔵で，寄棟造，桟瓦葺とする。外装は漆喰塗，腰を押縁下見板張とし，妻側と西面に大小の窓を配し，軒裏には鉢巻を廻す。簡素ではあるが，酒造製造工場の重要な施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004912"},{"id":"00008628","register_sub_id":"101","register_pk":"149349","name":"武勇煙突","kana":"ぶゆうえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県結城市大字結城字浦町144","lat":36.30337743,"lng":139.87261292,"geo_status":"db","era":"大正期／平成6年改修","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"煉瓦造、高さ11m","structure_material":"煉瓦造","registered":"2011.07.25(平成23.07.25)","register_no":"08 － 0248","desc":"脇蔵の南、仕込蔵と旧釜蔵が造る入隅に位置する。旧釜場蔵地下の釜場と接続して、現在も使用されている。煉瓦造。高さ11ｍで、東西1.2ｍ南北1.1ｍの矩形平面になる。土蔵漆喰仕上げの白と煉瓦色が好対照をなし、地域に親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008628"},{"id":"00008627","register_sub_id":"101","register_pk":"149348","name":"武勇旧釜蔵","kana":"ぶゆうきゅうかまぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県結城市大字結城字浦町144","lat":36.3034124,"lng":139.87252004,"geo_status":"db","era":"明治37年／平成6年改修","year":1904,"year_source":"converted","year_min":1904,"year_max":1904,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積60㎡、保冷室付","structure_material":"土蔵造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"08 － 0247","desc":"仕込蔵の西北に接する。桁行11ｍ梁間5.6ｍ、土蔵造平屋建、東西棟の切妻造桟瓦葺。北面西半に南北棟の切妻造、桁行8.9ｍ梁間3.6ｍ、木造平屋建の保冷室を付す。漆喰上げの妻面を大きく見せる旧釜蔵と、低い棟の真壁造の保冷室が変化ある外観をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008627"},{"id":"00008626","register_sub_id":"101","register_pk":"149347","name":"武勇仕込蔵","kana":"ぶゆうしこみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県結城市大字結城字浦町144","lat":36.30324957,"lng":139.87259872,"geo_status":"db","era":"明治42年","year":1909,"year_source":"converted","year_min":1909,"year_max":1909,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積207㎡","structure_material":"土蔵造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"08 － 0246","desc":"敷地のほぼ中央、脇蔵の南方、製品蔵の西に隣接する。桁行25ｍ梁間8.1ｍの土蔵造平屋建、南北棟の切妻造桟瓦葺、。漆喰仕上げで、腰高に水切りをまわす。南北両妻面に鉄製引込戸をたてる。内部には1室で、独立柱八本をたて、漆喰仕上げの真壁とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008626"},{"id":"00008625","register_sub_id":"101","register_pk":"149346","name":"武勇製品蔵","kana":"ぶゆうせいひんぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県結城市大字結城字浦町144","lat":36.30316734,"lng":139.87271783,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積318㎡","structure_material":"土蔵造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"08 － 0245","desc":"見世蔵の南に隣接する。土蔵造二階建、桁行23ｍ梁間14ｍ。南北棟の切妻造桟瓦葺、西面は全体にわたり、葺き降ろす。北面に出入口を開け、見世蔵と連絡する。漆喰仕上げで、鉢巻まで高く下見板を張る。大規模な蔵で、老舗酒造の風格を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008625"},{"id":"00008623","register_sub_id":"101","register_pk":"149344","name":"武勇見世蔵","kana":"ぶゆうみせぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"茨城県","address":"茨城県結城市大字結城字浦町144","lat":36.30336705,"lng":139.8728181,"geo_status":"db","era":"江戸末期／昭和20年頃改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積224㎡","structure_material":"木造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"08 － 0243","desc":"通りに北面して建つ。木造2階建、建築面積224㎡。南北棟の寄棟造を中心に、通り寄りに東へ切妻屋根を延ばす。桟瓦葺。大壁造で漆喰仕上げとし、1階は東寄りに出入口を構え、西は腰に大谷石を積み、中央上部に窓を造る。どっしりとした構えになる店舗。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008623"},{"id":"00008624","register_sub_id":"101","register_pk":"149345","name":"武勇脇蔵","kana":"ぶゆうわきぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県結城市大字結城字浦町144","lat":36.30342196,"lng":139.87276892,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積49㎡","structure_material":"土蔵造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"08 － 0244","desc":"見世蔵の西に隣接して、通りに沿って建つ。土蔵造2階建、東西棟の切妻造桟瓦葺、桁行11ｍ梁間4.5ｍ。漆喰仕上げで、通りに面して腰に石を貼り、その上部を竪板張とする。南面に引込戸の出入口を設ける。見世蔵とともに、重厚な通り景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008624"},{"id":"00001996","register_sub_id":"101","register_pk":"102986","name":"村井醸造石蔵","kana":"むらいじょうぞういしぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県桜川市真壁町真壁200-1","lat":36.27682193,"lng":140.10032462,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"石造平屋建、瓦葺、建築面積145㎡","structure_material":"石造平屋建","registered":"2000.12.04(平成12.12.04)","register_no":"08 － 0046","desc":"石蔵は道路を挟んだ脇蔵の対面に建つ。桁行１２間の長大な切妻造・妻入の建物で，内部は３室に分かれ，道路側の南面と扉口のある東面に下屋庇を設ける。木造軸組にキングポストトラスを架け，外側を大谷石積とした形式で，大正期の倉庫建築の良好な事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001996"},{"id":"00004326","register_sub_id":"101","register_pk":"105316","name":"村井醸造煙突","kana":"むらいじょうぞうえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"茨城県","address":"茨城県桜川市真壁町真壁72","lat":36.27636083,"lng":140.10016204,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"鉄筋コンクリート造、高さ22m","structure_material":"鉄筋コンクリート造","registered":"2004.11.08(平成16.11.08)","register_no":"08 － 0156","desc":"店舗と土蔵の間に置かれ，基部直径１．４５ｍ，高さ２２ｍの規模を有する。当時の最新の技術を用いた鉄筋コンクリート造で，煙道口はアーチ積とし，内部には耐火煉瓦を積み，頂上付近には櫛形の装飾を施す。町の景観を特徴づける工作物のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004326"},{"id":"00001995","register_sub_id":"101","register_pk":"102985","name":"村井醸造脇蔵","kana":"むらいじょうぞうわきぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁72","lat":36.27683398,"lng":140.10018366,"geo_status":"db","era":"明治35以前","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積105㎡","structure_material":"土蔵造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"08 － 0045","desc":"村井家は江戸中期頃から醸造業を営んだ旧家で，真壁の中心部に位置する。もと穀蔵の脇蔵は，桁行７間，梁間４間の規模で，南北棟の切妻造・桟瓦葺屋根をかける。丁寧な切石積の基礎，腰の縦板壁と上部の漆喰壁が調和し，角地の歴史的景観を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001995"},{"id":"00001551","register_sub_id":"101","register_pk":"102541","name":"結城酒造株式会社煉瓦煙突","kana":"ゆうきしゅぞうかぶしきがいしゃれんがえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県結城市大字結城1589","lat":36.30500567,"lng":139.87183556,"geo_status":"db","era":"明治36","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"煉瓦造、高さ10m","structure_material":"煉瓦造","registered":"2000.04.28(平成12.04.28)","register_no":"08 － 0023","desc":"高さ約１０ｍの煉瓦煙突は，安政蔵の北側にあり，明治３６年の建設と伝える。安政蔵の釜場と地下の煙道で結ばれており，酒造施設の近代的な工夫がうかがえるとともに，商業都市として栄え，酒造業も盛んであった結城の景観のシンボルともなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001551"},{"id":"00011884","register_sub_id":"101","register_pk":"211058","name":"飯沼本家裏門及び塀","kana":"いいぬまほんけうらもんおよびへい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"千葉県","address":"千葉県印旛郡酒々井町馬橋字場々106-1","lat":35.709437,"lng":140.272092,"geo_status":"db","era":"昭和29年頃","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"裏門 木造、瓦葺、間口2.8m 塀 木造、銅板葺、総延長3.6m、潜戸付","structure_material":"裏門 木造","registered":"2017.10.27(平成29.10.27)","register_no":"12-242","desc":"敷地東面を画す門。間口二・八メートルの一戸薬医門で、切妻造、桟瓦葺。北側に潜戸を開き、南北袖塀付で、北側は斜めに取り付く。五平の本柱上に冠木を渡し、男梁を架けて桁を受け、棟木は束で受ける簡素な構造。通りからの景観に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011884"},{"id":"00011883","register_sub_id":"101","register_pk":"211057","name":"飯沼本家甲子蔵","kana":"いいぬまほんけきのえねぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"千葉県","address":"千葉県印旛郡酒々井町馬橋字場々105-7他","lat":35.709279,"lng":140.27204,"geo_status":"db","era":"昭和15年頃／昭和前期移築","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造2階一部平屋建、鉄板葺及び鋼板葺、建築面積382㎡","structure_material":"木造2階一部平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"12-241","desc":"主屋東方に西面する。桁行一六間、梁間九間、切妻造で越屋根を付け、北西角に応接室を張出す。外壁は腰を板張、上部を漆喰塗とし、小屋組はクイーンポストトラスである。応接室は、扇状に配った天井や幾何学模様の欄間など、様々な意匠を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011883"},{"id":"00011882","register_sub_id":"101","register_pk":"211056","name":"飯沼本家明治蔵","kana":"いいぬまほんけめいじぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県印旛郡酒々井町馬橋字場々107-1他","lat":35.709672,"lng":140.271887,"geo_status":"db","era":"明治中期／昭和30年代改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階一部平屋建、鋼板葺、建築面積291㎡","structure_material":"土蔵造2階一部平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"12-240","desc":"敷地北東隅に南面する。桁行一六間、梁間八間、切妻造、鋼板葺で、南面に検査場を張り出す。内部は一室であり、上屋柱筋に直径一尺二寸の丸太材の柱を二間置きに立て、二階では柱上に二段に組んだ梁組をみせる。酒造施設に欠かせない大規模な蔵を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011882"},{"id":"00012104","register_sub_id":"101","register_pk":"352903","name":"石上酒造麹室","kana":"いしがみしゅぞうこうじむろ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県銚子市田中町7-1","lat":35.73263,"lng":140.842559,"geo_status":"db","era":"明治29年頃","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"石造平屋建、金属板葺、建築面積42㎡","structure_material":"石造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"12-249","desc":"敷地南寄り、米蔵の西に建つ。大谷石による組積造で、壁体には厚さ三〇センチメートルの大谷石を長手方向に積む。屋根は切妻造鉄板葺。内部は全面杉板張とし、壁体との間には保温のために籾殻を詰め、天井板上にも藁を敷く。酒造業に欠かせない麹室の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012104"},{"id":"00012103","register_sub_id":"101","register_pk":"352902","name":"石上酒造米蔵","kana":"いしがみしゅぞうこめぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県銚子市田中町7-1","lat":35.73263,"lng":140.842662,"geo_status":"db","era":"明治中期／平成23年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造平屋建、瓦葺、建築面積29㎡","structure_material":"土蔵造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"12-248","desc":"銚子市街の中心地に位置し、南北棟で建つ土蔵造二階建で、屋根は切妻造桟瓦葺とする。室内は一、二階とも一室とし、一階は土間叩きとする。外壁は腰海鼠壁、上部漆喰塗で軒まで塗込めるが、中層部には鋼板を張っている。敷地建物群南東端を画す土蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012103"},{"id":"00012105","register_sub_id":"101","register_pk":"352904","name":"石上酒造仕込蔵（醪蔵）","kana":"いしがみしゅぞうしこみぐら（もろみぐら）","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県銚子市田中町7-1","lat":35.732641,"lng":140.842502,"geo_status":"db","era":"明治35年頃","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"石造2階建、瓦葺、建築面積86㎡","structure_material":"石造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"12-250","desc":"敷地の西南隅に建つ石造蔵。大谷石を積む壁構造で、屋根は切妻造桟瓦葺。内部は一、二階とも一室とし、小屋組は一階基礎を高く設けて木造側柱を立ち上げ、クイーンポストトラスを支える。酒造業の中核をなす蔵で、地域の歴史的景観に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012105"},{"id":"00012106","register_sub_id":"101","register_pk":"352905","name":"石上酒造貯蔵蔵","kana":"いしがみしゅぞうちょぞうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県銚子市田中町7-1","lat":35.732767,"lng":140.842518,"geo_status":"db","era":"明治35年頃","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"石造平屋建、瓦葺、建築面積146㎡","structure_material":"石造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"12-251","desc":"仕込蔵の北に接して建つ。桁行一八・五メートル、梁間七・九メートルの規模で、内部は土間の一室とし、絞り機や醸造タンクを収める。壁体は大谷石の長手積で、キングポストトラスに切妻造桟瓦葺とする。酒造の中核をなす蔵で地域の歴史的景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012106"},{"id":"00012107","register_sub_id":"101","register_pk":"352906","name":"石上酒造文庫蔵","kana":"いしがみしゅぞうぶんこくら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県銚子市田中町7-1","lat":35.732901,"lng":140.842514,"geo_status":"db","era":"明治35年頃／平成23年改修","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積40㎡","structure_material":"土蔵造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"12-252","desc":"敷地北西隅に南北棟で建つ。桁行七・七メートル、梁間五・九メートルのほぼ正方形平面で、東面に扉口を開く。コンクリート基礎上に基礎石を置き、漆喰壁を立ち上げ、屋根は切妻造桟瓦葺とする。街路に面する北妻面二階には左右に窓を開き、アクセントとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012107"},{"id":"00007458","register_sub_id":"101","register_pk":"108440","name":"鶴泉堂菓子店石倉庫","kana":"かくせんどうかしてんいしそうこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"千葉県","address":"千葉県匝瑳市八日市場イ2871","lat":35.7009041,"lng":140.54844528,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"石造2階地下1階建、瓦葺、建築面積30㎡","structure_material":"石造2階地下1階建","registered":"2009.01.08(平成21.01.08)","register_no":"12 － 0117","desc":"敷地南端に建つ。桁行５．５ｍ梁間３．６ｍ、地上２階地下１階建の石蔵で、東西棟の切妻造桟瓦葺。北面に瓦葺庇を掛けて出入口を設け、上部に庇付窓を穿つ。切石を積み上げ壁面を造り、水切りや鉢巻をまわす。大谷石の柔らかい風合いが落ち着いた景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007458"},{"id":"00007457","register_sub_id":"101","register_pk":"108439","name":"鶴泉堂菓子店店舗兼主屋","kana":"かくせんどうかしてんてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"千葉県","address":"千葉県匝瑳市八日市場イ2871","lat":35.70112928,"lng":140.54845652,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺、建築面積69㎡","structure_material":"木造2階建","registered":"2009.01.08(平成21.01.08)","register_no":"12 － 0116","desc":"通りに二面する南北に長い敷地の北端に建つ。間口６．６ｍ奥行１０ｍの木造２階建。寄棟造妻入桟瓦葺で、出桁造で垂木を配る。北正面から小路に面した西側に下屋庇をまわし、鉤の手にガラス戸をたて開放的に扱う。昭和前期における建ちの高い町家の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007457"},{"id":"00013349","register_sub_id":"101","register_pk":"368437","name":"キノエネ醤油旧火入場及び変電室","kana":"きのえねしょうゆきゅうひいればおよびへんでんしつ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"大正","pref":"千葉県","address":"千葉県野田市中野台字久保之内157他","lat":35.94756667,"lng":139.86055833,"geo_status":"db","era":"大正10年／昭和28年増築、同51年改修","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"鉄筋コンクリート造3階一部煉瓦造及び木造2階建、瓦葺、建築面積82㎡","structure_material":"鉄筋コンクリート造3階一部煉瓦造及び木造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"12 － 0299","desc":"敷地南辺東寄りの正門を入って正面に建つ。鉄筋コンクリート造三階建、切妻造セメント瓦葺の火入場と、一階煉瓦造、二階木造で、パラペットを立上げた変電室からなる。火入場の小屋はキングポストトラス組とする。野田で最初期の鉄筋コンクリート造建築物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013349"},{"id":"00013348","register_sub_id":"101","register_pk":"368436","name":"キノエネ醤油事務所兼主屋","kana":"きのえねしょうゆじむしょけんおもや","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県野田市中野台字久保之内157他","lat":35.9474,"lng":139.86069167,"geo_status":"db","era":"明治30年／明治36年増築","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造2階建、瓦葺、建築面積167㎡","structure_material":"木造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"12 － 0298","desc":"野田市街に位置し、敷地南辺東寄りに開く正門脇に西面して建つ。切妻造桟瓦葺平入の事務所東側に入母屋造東西棟の主屋が続く。事務所正面外観にはガラス窓を配し、一階に事務室と洋風の応接室を配す。地場産業である醤油工場の施設として景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013348"},{"id":"00008259","register_sub_id":"101","register_pk":"133901","name":"旧浅子神輿店店舗兼主屋","kana":"きゅうあさこみこしてんてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"千葉県","address":"千葉県市川市本行徳37-2","lat":35.69043123,"lng":139.91553178,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、瓦葺、建築面積103㎡","structure_material":"木造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"12 － 0149","desc":"旧行徳街道に東面する。間口６．４ｍの木造２階建、切妻造桟瓦葺で、背面に平屋建の居室が続く。１階は前寄り半間に土間を通し、板床の広い作業場とし、２階はトコや平書院を設ける。上屋は出桁造、下屋は軒桁を架け、開放とする。木太く、力強い印象の町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008259"},{"id":"00007616","register_sub_id":"101","register_pk":"108598","name":"宍倉弥兵衛商店店舗兼主屋","kana":"ししくらやへえしょうてんてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県夷隅郡大多喜町大多喜字下南郭60-1","lat":35.28287104,"lng":140.2454339,"geo_status":"db","era":"明治7／昭和29・昭和41・平成17改修","year":1874,"year_source":"db","year_min":1874,"year_max":1874,"year_label":null,"structure":"木造2階建、瓦葺、建築面積116㎡","structure_material":"木造2階建","registered":"2009.04.28(平成21.04.28)","register_no":"12 － 0124","desc":"夷隅神社の西北、通りに東面して建つ。木造２階建の町家で、寄棟造桟瓦葺とし、正面及び南面、背面に庇を付ける。１階に店舗、２階に居室等を配する。出桁造で疎らに垂木を配り、２階正面は南半部を真壁、北半部を出格子窓とする。伝統的な町家の佇まいを残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007616"},{"id":"00002613","register_sub_id":"101","register_pk":"103603","name":"鈴木家住宅穀蔵","kana":"すずきけじゅうたくこくぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県鴨川市西町1139-3","lat":35.11645671,"lng":140.11482581,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積99㎡","structure_material":"土蔵造2階建","registered":"2002.02.14(平成14.02.14)","register_no":"12 － 0048","desc":"主屋の東南東に建つ。桁行４間，梁間３間規模の南北棟，桟瓦葺，切妻造，平入で，西面には土庇を架ける。酒米を納めた蔵で，外壁を漆喰塗とし，１階部には下見板張りを施す。東門への通路を隔てて火入れ蔵の北方に位置し，両者で造り酒屋の屋敷景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002613"},{"id":"00002612","register_sub_id":"101","register_pk":"103602","name":"鈴木家住宅火入れ蔵","kana":"すずきけじゅうたくひいれぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県鴨川市西町1139-3","lat":35.11634713,"lng":140.11486023,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造平屋建、瓦葺、建築面積121㎡","structure_material":"土蔵造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"12 － 0047","desc":"主屋の東南方，敷地東辺の門の近くに建つ。桁行６間，梁間４間規模の東西棟，桟瓦葺，切妻造，妻入で，西妻面に１間半幅の下屋を差し出して検査室等とする。酒造最終工程の腐敗防止処理と出荷までの貯蔵をなす蔵であり，造り酒屋の屋敷構えを構成する要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002612"},{"id":"00001172","register_sub_id":"101","register_pk":"102162","name":"寺田本家醸造蔵","kana":"てらだほんけじょうぞうぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県香取郡神崎町神崎本宿1964","lat":35.90540155,"lng":140.40153507,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"煉瓦造平屋建，瓦葺，建築面積241㎡","structure_material":"煉瓦造平屋建","registered":"1999.07.08(平成11.07.08)","register_no":"12 － 0014","desc":"延宝年間（１６７３年）創業と伝える酒造家の醸造蔵。煉瓦造２階建で、瓦葺寄棟屋根の南面に切妻の屋根窓を張出す。煉瓦積はイギリス積、小屋組はクイーンポストトラスで、対束の頭部を繋ぐ水平材を挟み梁とするなど構法上にも見どころがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001172"},{"id":"00008823","register_sub_id":"101","register_pk":"162266","name":"豊乃鶴酒造煙突","kana":"とよのつるしゅぞうえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"昭和中","pref":"千葉県","address":"千葉県夷隅郡大多喜町新丁字下宿88","lat":35.2844955,"lng":140.24725389,"geo_status":"db","era":"昭和23年頃","year":1948,"year_source":"db","year_min":1948,"year_max":1948,"year_label":null,"structure":"煉瓦造、高さ16m","structure_material":"煉瓦造","registered":"2011.10.28(平成23.10.28)","register_no":"12 － 0159","desc":"工場の正面の西寄りに位置する。基礎部分は方1.6ｍの正方形平面で、高さ16ｍを測る。イギリス積で積み上げ、頂部は三段に迫り出す。足下には点検口を設ける。重厚な工場前にそびえ立つ煉瓦造煙突で、酒醸造所らしい景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008823"},{"id":"00008821","register_sub_id":"101","register_pk":"162264","name":"豊乃鶴酒造工場","kana":"とよのつるしゅぞうこうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県夷隅郡大多喜町新丁字下宿88","lat":35.28463378,"lng":140.24728979,"geo_status":"db","era":"明治8年頃","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積417㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"12 － 0157","desc":"敷地北奥に位置する。建築面積417㎡と大規模な木造平屋建。南北棟の切妻造桟瓦葺2棟を東西に並べ、南面に下屋を通して入母屋造風の外観とする。外観は、妻を塗り込め、東棟をやや低くして変化を与え、内部は真壁で、天井を張らず和小屋を現す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008821"},{"id":"00008822","register_sub_id":"101","register_pk":"162265","name":"豊乃鶴酒造酒蔵","kana":"とよのつるしゅぞうさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県夷隅郡大多喜町新丁字下宿88","lat":35.28474414,"lng":140.24709833,"geo_status":"db","era":"明治8年","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"木造2階建、瓦葺、建築面積213㎡","structure_material":"木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"12 － 0158","desc":"敷地西北隅に南北棟で建ち、西面は通りに面する。桁行15ｍ梁間9.1ｍ、切妻造桟瓦葺で、東面に梁間5.5ｍの下屋を付設する。内部は下屋を間仕切り、1階は1室の大空間とする。内壁は中塗の真壁で、半間ごとに柱を配する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008822"},{"id":"00001408","register_sub_id":"101","register_pk":"102398","name":"豊乃鶴酒造主屋","kana":"とよのつるしゅぞうしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県夷隅郡大多喜町新丁字下宿88","lat":35.28425135,"lng":140.24728328,"geo_status":"db","era":"明治7","year":1874,"year_source":"db","year_min":1874,"year_max":1874,"year_label":null,"structure":"木造2階建、瓦葺、建築面積134㎡","structure_material":"木造2階建","registered":"1999.11.18(平成11.11.18)","register_no":"12 － 0034","desc":"大多喜城下の市場町として栄えた集落に位置する造り酒屋の主屋。つし二階建ての町家で，座敷飾りに銘木を用いたり，二階の軒を出桁造とするなど質が高い建築であり，出窓格子，上げ戸などからなる表構えも，往時の趣を良く伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001408"},{"id":"00008820","register_sub_id":"101","register_pk":"162263","name":"豊乃鶴酒造精米所及び貯蔵庫","kana":"とよのつるしゅぞうせいまいじょおよびちょぞうこ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県夷隅郡大多喜町新丁字下宿88","lat":35.28429473,"lng":140.24753045,"geo_status":"db","era":"明治前期／平成22年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積114㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"12 － 0156","desc":"敷地東南隅に南北棟で建つ。桁行14ｍ梁間6.4ｍ、切妻造桟瓦葺で、北・西面に下屋を付設。内部は2室に分かれ、南を酒米貯蔵庫、北を精米所とする。外壁は高く下見板を張り、真壁の漆喰仕上げ。主屋とともに通りに面し敷地正面を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008820"},{"id":"00008819","register_sub_id":"101","register_pk":"162262","name":"豊乃鶴酒造店舗","kana":"とよのつるしゅぞうてんぽ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"千葉県","address":"千葉県夷隅郡大多喜町新丁字下宿88","lat":35.28442636,"lng":140.24722863,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺、建築面積66㎡","structure_material":"木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"12 － 0155","desc":"角地に占める敷地の中央に位置する。東面する入母屋造妻入桟瓦葺の木造2階建、建築面積66㎡。1階正面に下屋、2階に庇を付ける。正面にミセ、その奥に居室を配する。2階の主室はトコや棚などを構え、円窓を穿つなど瀟洒な座敷とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008819"}];
